screenPanels.initJs:
function(container, apiUrl, tables) {
  let currentForecastData = [];

  // 店舗データを読み込んでセレクトボックスに設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 予測結果テーブルの描画
  function renderForecastTable(results) {
    const tbody = container.querySelector('#forecast-table-body');
    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.予測結果ID}">
        <td>${result.商品コード || '-'}</td>
        <td>${result.商品名 || '-'}</td>
        <td>${result.予測対象日 ? new Date(result.予測対象日).toLocaleDateString() : '-'}</td>
        <td>${result.予測数量 || 0}</td>
        <td>${result.予測精度 || 0}%</td>
        <td>${result.推奨発注数量 || 0}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.予測結果ID}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // グラフ描画関数
  function drawForecastChart(data) {
    const canvas = container.querySelector('#forecast-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) return;

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの最大値・最小値を計算
    const maxValue = Math.max(...data.map(d => Math.max(d.予測数量 || 0, d.実績数量 || 0)));
    const minValue = 0;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // データポイントの描画
    if (data.length > 1) {
      const stepX = chartWidth / (data.length - 1);

      // 予測値の線
      ctx.strokeStyle = '#4a90e2';
      ctx.lineWidth = 2;
      ctx.beginPath();
      data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = padding + chartHeight - ((point.予測数量 || 0) / maxValue) * chartHeight;
        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();

      // 実績値の線（データがある場合）
      ctx.strokeStyle = '#ff6a00';
      ctx.lineWidth = 2;
      ctx.beginPath();
      let hasActual = false;
      data.forEach((point, index) => {
        if (point.実績数量 !== null && point.実績数量 !== undefined) {
          const x = padding + index * stepX;
          const y = padding + chartHeight - (point.実績数量 / maxValue) * chartHeight;
          if (!hasActual) {
            ctx.moveTo(x, y);
            hasActual = true;
          } else {
            ctx.lineTo(x, y);
          }
        }
      });
      if (hasActual) ctx.stroke();
    }

    // 凡例
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測値', padding + 10, 20);
    ctx.fillStyle = '#4a90e2';
    ctx.fillRect(padding + 60, 12, 20, 3);

    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('実績値', padding + 100, 20);
    ctx.fillStyle = '#ff6a00';
    ctx.fillRect(padding + 150, 12, 20, 3);
  }

  // 比較チャート描画
  function drawComparisonChart(data) {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) return;

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // 棒グラフの描画
    const barWidth = chartWidth / data.length * 0.8;
    const maxValue = Math.max(...data.map(d => Math.max(d.予測数量 || 0, d.実績数量 || 0)));

    data.forEach((point, index) => {
      const x = padding + (index * chartWidth / data.length);

      // 予測値の棒
      if (point.予測数量) {
        const height = (point.予測数量 / maxValue) * chartHeight;
        ctx.fillStyle = '#4a90e2';
        ctx.fillRect(x, padding + chartHeight - height, barWidth / 2, height);
      }

      // 実績値の棒
      if (point.実績数量) {
        const height = (point.実績数量 / maxValue) * chartHeight;
        ctx.fillStyle = '#ff6a00';
        ctx.fillRect(x + barWidth / 2, padding + chartHeight - height, barWidth / 2, height);
      }
    });
  }

  // 予測精度指標の更新
  function updateMetrics(data) {
    if (!data || data.length === 0) return;

    // 予測精度の平均を計算
    const validData = data.filter(d => d.予測精度 !== null && d.予測精度 !== undefined);
    const avgAccuracy = validData.length > 0 ? 
      (validData.reduce((sum, d) => sum + (d.予測精度 || 0), 0) / validData.length).toFixed(1) : '-';

    container.querySelector('#accuracy-value').textContent = avgAccuracy + '%';
    container.querySelector('#mae-value').textContent = '計算中...';
    container.querySelector('#r2-value').textContent = '計算中...';
  }

  // 影響要因分析の表示
  function updateFactorAnalysis() {
    const factorContainer = container.querySelector('#factor-analysis');
    const factors = [
      { name: '季節性', impact: '高', value: '85%' },
      { name: '天候', impact: '中', value: '62%' },
      { name: 'イベント', impact: '中', value: '58%' },
      { name: '曜日', impact: '低', value: '34%' }
    ];

    factorContainer.innerHTML = factors.map(factor => `
      <div class="factor-item">
        <span>${factor.name}</span>
        <span class="metric-value">${factor.value}</span>
      </div>
    `).join('');
  }

  // 天候・イベント情報の表示
  function updateWeatherAndEventInfo() {
    const weatherInfo = container.querySelector('#weather-info');
    const eventInfo = container.querySelector('#event-info');

    weatherInfo.innerHTML = `
      <p><strong>今日:</strong> 晴れ 最高気温: 25℃</p>
      <p><strong>明日:</strong> 曇り 最高気温: 23℃</p>
      <p><strong>週末:</strong> 雨の予報 最高気温: 20℃</p>
    `;

    eventInfo.innerHTML = `
      <p><strong>今週末:</strong> 地域祭り (来場者予想: 5,000人)</p>
      <p><strong>来週:</strong> 特売セール実施予定</p>
    `;
  }

  // バリデーション関数
  function validateForecastConditions() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const model = container.querySelector('#model-select').value;

    const errors = [];

    if (!storeId) errors.push('店舗を選択してください');
    if (!category) errors.push('商品カテゴリを選択してください');
    if (!startDate) errors.push('予測期間の開始日を設定してください');
    if (!endDate) errors.push('予測期間の終了日を設定してください');
    if (!model) errors.push('予測モデルを選択してください');

    if (startDate && endDate && new Date(startDate) >= new Date(endDate)) {
      errors.push('開始日は終了日より前の日付を入力してください');
    }

    if (startDate && new Date(startDate) < new Date()) {
      errors.push('開始日は現在日以降の日付を設定してください');
    }

    return errors;
  }

  // エラーメッセージ表示
  function showError(messages) {
    const errorDiv = container.querySelector('#error-message');
    if (messages.length > 0) {
      errorDiv.innerHTML = messages.map(msg => `<p>${msg}</p>`).join('');
      errorDiv.classList.remove('hidden');
    } else {
      errorDiv.classList.add('hidden');
    }
  }

  // CSV エクスポート
  function exportForecastResults() {
    if (currentForecastData.length === 0) {
      alert('エクスポートする予測結果がありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測対象日', '予測数量', '予測精度', '推奨発注数量'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentForecastData.map(row => [
        row.商品コード || '',
        row.商品名 || '',
        row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : '',
        row.予測数量 || 0,
        (row.予測精度 || 0) + '%',
        row.推奨発注数量 || 0
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();

  // 今日の日付を開始日のデフォルトに設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#start-date').value = today;

  // 1週間後を終了日のデフォルトに設定
  const nextWeek = new Date();
  nextWeek.setDate(nextWeek.getDate() + 7);
  container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#btn-execute-forecast').addEventListener('click', async () => {
    const errors = validateForecastConditions();
    if (errors.length > 0) {
      showError(errors);
      return;
    }

    showError([]);

    // 処理中表示
    container.querySelector('#forecast-processing').classList.remove('hidden');
    container.querySelector('#forecast-results').classList.add('hidden');

    try {
      // 模擬的な予測処理（実際はAPIを呼び出し）
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 模擬データで結果表示
      const mockResults = [
        {
          予測結果ID: '1',
          商品コード: 'P001',
          商品名: 'おにぎり（鮭）',
          予測対象日: new Date().toISOString(),
          予測数量: 45,
          予測精度: 87,
          推奨発注数量: 50,
          実績数量: 42
        },
        {
          予測結果ID: '2',
          商品コード: 'P002',
          商品名: 'サンドイッチ',
          予測対象日: new Date().toISOString(),
          予測数量: 32,
          予測精度: 82,
          推奨発注数量: 35,
          実績数量: 30
        }
      ];

      currentForecastData = mockResults;

      // 結果表示
      container.querySelector('#forecast-processing').classList.add('hidden');
      container.querySelector('#forecast-results').classList.remove('hidden');

      renderForecastTable(mockResults);
      drawForecastChart(mockResults);
      drawComparisonChart(mockResults);
      updateMetrics(mockResults);
      updateFactorAnalysis();
      updateWeatherAndEventInfo();

    } catch (error) {
      showError(['予測処理中にエラーが発生しました: ' + error.message]);
      container.querySelector('#forecast-processing').classList.add('hidden');
    }
  });

  container.querySelector('#btn-clear-conditions').addEventListener('click', () => {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#start-date').value = today;
    container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];
    container.querySelector('#model-select').value = '';
    container.querySelector('#seasonal-factor').checked = false;
    container.querySelector('#event-factor').checked = false;
    container.querySelector('#weather-factor').checked = false;
    showError([]);
  });

  container.querySelector('#btn-export-forecast').addEventListener('click', exportForecastResults);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen('scr-1778591885672'); // AI需要予測処理画面へ遷移
    }
  });
}

function(container, apiUrl, tables) {
  let currentProducts = [];
  let stores = [];
  let categories = [];
  let predictions = [];

  // 初期データの設定
  const storeTable = tables.find(t => t.tableName === '店舗マスタ') || { records: [] };
  const productTable = tables.find(t => t.tableName === '商品マスタ') || { records: [] };
  const predictionTable = tables.find(t => t.tableName === '需要予測結果') || { records: [] };
  const orderTable = tables.find(t => t.tableName === '発注データ') || { records: [] };

  stores = storeTable.records || [];
  predictions = predictionTable.records || [];

  // 店舗選択肢の初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // カテゴリ選択肢の初期化
  function initCategoryOptions() {
    const categorySelect = container.querySelector('#category-select');
    const uniqueCategories = [...new Set(currentProducts.map(p => p.商品カテゴリID))];
    categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>';
    uniqueCategories.forEach(categoryId => {
      if (categoryId) {
        categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId.slice(-8)}</option>`;
      }
    });
  }

  // 商品テーブルの再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    const tableContainer = container.querySelector('#product-table-container');
    const noStoreMessage = container.querySelector('#no-store-message');
    const noResultsMessage = container.querySelector('#no-results-message');

    if (!container.querySelector('#store-select').value) {
      tableContainer.classList.add('hidden');
      noStoreMessage.classList.remove('hidden');
      noResultsMessage.classList.add('hidden');
      return;
    }

    noStoreMessage.classList.add('hidden');

    if (products.length === 0) {
      tableContainer.classList.add('hidden');
      noResultsMessage.classList.remove('hidden');
      return;
    }

    noResultsMessage.classList.add('hidden');
    tableContainer.classList.remove('hidden');

    tbody.innerHTML = products.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === container.querySelector('#store-select').value);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const recommendedQty = prediction ? prediction.推奨発注数量 : 0;
      const currentStock = Math.floor(Math.random() * 100) + 10; // 仮の在庫数

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${currentStock}</td>
          <td>${predictedQty}</td>
          <td>${recommendedQty}</td>
          <td><input type="number" class="input order-qty-input" data-id="${product.商品ID}" min="0" style="width: 80px;" value="${recommendedQty}"></td>
          <td><input type="text" class="input order-reason-input" data-id="${product.商品ID}" placeholder="発注理由" style="width: 120px;"></td>
          <td>
            <button class="action-btn secondary adjust-btn" data-id="${product.商品ID}" data-action="increase">+</button>
            <button class="action-btn secondary adjust-btn" data-id="${product.商品ID}" data-action="decrease">-</button>
            <button class="action-btn order-single-btn" data-id="${product.商品ID}">発注</button>
          </td>
        </tr>
      `;
    }).join('');

    updatePredictionSummary(products);
  }

  // 需要予測サマリーの更新
  function updatePredictionSummary(products) {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      container.querySelector('#prediction-count').textContent = '-';
      container.querySelector('#prediction-total').textContent = '-';
      container.querySelector('#prediction-amount').textContent = '-';
      return;
    }

    const storePredictions = predictions.filter(p => p.店舗ID === storeId);
    const totalPredicted = storePredictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
    const totalAmount = storePredictions.reduce((sum, p) => {
      const product = products.find(prod => prod.商品ID === p.商品ID);
      return sum + ((p.推奨発注数量 || 0) * (product?.単価 || 0));
    }, 0);

    container.querySelector('#prediction-count').textContent = storePredictions.length;
    container.querySelector('#prediction-total').textContent = totalPredicted.toLocaleString();
    container.querySelector('#prediction-amount').textContent = '¥' + totalAmount.toLocaleString();
  }

  // 商品データの読み込み
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(1); // 商品マスタのインデックス
      if (products) {
        currentProducts = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);
        initCategoryOptions();
        applyFilters();
      }
    } catch (error) {
      console.error('商品データの読み込みに失敗しました:', error);
    }
  }

  // フィルターの適用
  function applyFilters() {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const productSearch = container.querySelector('#product-search').value.toLowerCase();

    if (!storeId) {
      renderProducts([]);
      return;
    }

    let filtered = currentProducts.filter(product => {
      const matchesCategory = !categoryId || product.商品カテゴリID === categoryId;
      const matchesSearch = !productSearch || 
        (product.商品名 && product.商品名.toLowerCase().includes(productSearch)) ||
        (product.商品コード && product.商品コード.toLowerCase().includes(productSearch));

      return matchesCategory && matchesSearch;
    });

    renderProducts(filtered);
  }

  // バリデーション関数
  function validateOrderQuantity(qty) {
    if (qty === '' || qty === null || qty === undefined) {
      return { valid: false, message: '発注量を入力してください' };
    }

    const numQty = Number(qty);
    if (isNaN(numQty)) {
      return { valid: false, message: '発注量は数値で入力してください' };
    }

    if (numQty < 0) {
      return { valid: false, message: '発注量は正の数値を入力してください' };
    }

    if (numQty === 0) {
      return { valid: false, message: '発注量は1以上を入力してください' };
    }

    return { valid: true };
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start').value;
    const endDate = container.querySelector('#date-end').value;

    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('終了日は開始日以降の日付を入力してください');
      return false;
    }
    return true;
  }

  // 発注処理
  async function processOrder(productIds) {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const orderItems = [];
    let hasError = false;

    for (const productId of productIds) {
      const qtyInput = container.querySelector(`input.order-qty-input[data-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason-input[data-id="${productId}"]`);

      if (!qtyInput) continue;

      const qty = qtyInput.value.trim();
      const validation = validateOrderQuantity(qty);

      if (!validation.valid) {
        alert(`商品ID ${productId}: ${validation.message}`);
        qtyInput.focus();
        hasError = true;
        break;
      }

      const product = currentProducts.find(p => p.商品ID === productId);
      const prediction = predictions.find(p => p.商品ID === productId && p.店舗ID === storeId);

      orderItems.push({
        店舗ID: storeId,
        商品ID: productId,
        需要予測結果ID: prediction?.予測結果ID || null,
        発注日: new Date().toISOString(),
        納期予定日: new Date(Date.now() + (product?.リードタイム日数 || 3) * 24 * 60 * 60 * 1000).toISOString(),
        発注数量: Number(qty),
        予測数量: prediction?.予測数量 || 0,
        発注単価: product?.単価 || 0,
        発注金額: Number(qty) * (product?.単価 || 0),
        発注方法: prediction && Number(qty) === prediction.推奨発注数量 ? 'AI推奨採用' : 'AI推奨修正',
        発注ステータス: '発注済',
        仕入先ID: product?.仕入先ID || '',
        発注理由: reasonInput?.value || '',
        承認者ID: null,
        承認日時: null,
        自動発注フラグ: false,
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      });
    }

    if (hasError) return;

    // 発注確認モーダルの表示
    showOrderConfirmation(orderItems);
  }

  // 発注確認モーダルの表示
  function showOrderConfirmation(orderItems) {
    const modal = container.querySelector('#order-modal');
    const detailsDiv = container.querySelector('#order-details');

    const totalAmount = orderItems.reduce((sum, item) => sum + item.発注金額, 0);
    const totalQty = orderItems.reduce((sum, item) => sum + item.発注数量, 0);

    detailsDiv.innerHTML = `
      <div style="margin-bottom: 15px;">
        <strong>発注サマリー</strong><br>
        商品数: ${orderItems.length}点<br>
        総発注量: ${totalQty.toLocaleString()}個<br>
        総発注金額: ¥${totalAmount.toLocaleString()}
      </div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>発注量</th>
              <th>単価</th>
              <th>金額</th>
              <th>発注理由</th>
            </tr>
          </thead>
          <tbody>
            ${orderItems.map(item => {
              const product = currentProducts.find(p => p.商品ID === item.商品ID);
              return `
                <tr>
                  <td>${product?.商品名 || ''}</td>
                  <td>${item.発注数量.toLocaleString()}</td>
                  <td>¥${item.発注単価.toLocaleString()}</td>
                  <td>¥${item.発注金額.toLocaleString()}</td>
                  <td>${item.発注理由 || '-'}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');

    // 発注実行ボタンのイベント
    container.querySelector('#btn-confirm-order').onclick = async () => {
      try {
        for (const item of orderItems) {
          await window.aivicApi.save(7, item); // 発注データテーブルのインデックス
        }
        alert('発注が完了しました');
        modal.classList.add('hidden');

        // 発注量と理由をリセット
        orderItems.forEach(item => {
          const qtyInput = container.querySelector(`input.order-qty-input[data-id="${item.商品ID}"]`);
          const reasonInput = container.querySelector(`input.order-reason-input[data-id="${item.商品ID}"]`);
          if (qtyInput) qtyInput.value = '';
          if (reasonInput) reasonInput.value = '';
        });

      } catch (error) {
        alert('発注処理中にエラーが発生しました');
        console.error(error);
      }
    };
  }

  // CSVエクスポート
  function exportCSV() {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const headers = ['商品コード', '商品名', '現在在庫', '予測需要量', '推奨発注量', '発注量', '発注理由'];
    const rows = Array.from(container.querySelectorAll('#product-tbody tr')).map(row => {
      const cells = row.querySelectorAll('td');
      const qtyInput = row.querySelector('.order-qty-input');
      const reasonInput = row.querySelector('.order-reason-input');

      return [
        cells[1]?.textContent || '',
        cells[2]?.textContent || '',
        cells[3]?.textContent || '',
        cells[4]?.textContent || '',
        cells[5]?.textContent || '',
        qtyInput?.value || '',
        reasonInput?.value || ''
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  initStoreOptions();

  // イベントリスナーの設定
  container.querySelector('#store-select').addEventListener('change', () => {
    loadProducts();
  });

  container.querySelector('#category-select').addEventListener('change', applyFilters);
  container.querySelector('#product-search').addEventListener('input', applyFilters);

  container.querySelector('#btn-search').addEventListener('click', () => {
    if (validateDateRange()) {
      applyFilters();
    }
  });

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#product-search').value = '';
    container.querySelector('#date-start').value = '';
    container.querySelector('#date-end').value = '';
    renderProducts([]);
  });

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const checkedBoxes = container.querySelectorAll('.product-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }
    const productIds = Array.from(checkedBoxes).map(cb => cb.dataset.id);
    processOrder(productIds);
  });

  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#order-modal').classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const adjustBtn = e.target.closest('.adjust-btn');
    if (adjustBtn) {
      const productId = adjustBtn.dataset.id;
      const action = adjustBtn.dataset.action;
      const qtyInput = container.querySelector(`input.order-qty-input[data-id="${productId}"]`);

      if (qtyInput) {
        let currentQty = Number(qtyInput.value) || 0;
        if (action === 'increase') {
          qtyInput.value = currentQty + 1;
        } else if (action === 'decrease' && currentQty > 0) {
          qtyInput.value = currentQty - 1;
        }
      }
      return;
    }

    const orderBtn = e.target.closest('.order-single-btn');
    if (orderBtn) {
      const productId = orderBtn.dataset.id;
      processOrder([productId]);
      return;
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#order-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#order-modal')) {
      container.querySelector('#order-modal').classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  let autoRefreshInterval = null;
  let isAutoRefreshEnabled = false;

  // ステータス表示用の関数
  function getStatusBadge(status) {
    const statusMap = {
      '成功': { color: '#4ade80', text: '成功' },
      '失敗': { color: '#f87171', text: '失敗' },
      '警告': { color: '#fbbf24', text: '警告' },
      '実行中': { color: '#60a5fa', text: '実行中' }
    };
    const s = statusMap[status] || { color: '#9ca3af', text: status };
    return `<span style="background: ${s.color}; color: #1a2a40; padding: 2px 8px; border-radius: 12px; font-size: 0.8em; font-weight: bold;">${s.text}</span>`;
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
  }

  // サマリー更新関数
  function updateSummary(logs) {
    const total = logs.length;
    const success = logs.filter(log => log.処理ステータス === '成功').length;
    const error = logs.filter(log => log.処理ステータス === '失敗').length;
    const lastRun = logs.length > 0 ? 
      formatDateTime(logs.sort((a, b) => new Date(b.収集開始日時) - new Date(a.収集開始日時))[0].収集開始日時) : '-';

    container.querySelector('#summary-total').textContent = total;
    container.querySelector('#summary-success').textContent = success;
    container.querySelector('#summary-error').textContent = error;
    container.querySelector('#summary-last-run').textContent = lastRun;

    // エラー状況インジケーター更新
    const errorIndicator = container.querySelector('#error-indicator');
    const statusIcon = container.querySelector('#status-icon');
    const statusText = container.querySelector('#status-text');

    if (error > 0) {
      errorIndicator.style.borderLeftColor = '#f87171';
      statusIcon.style.background = '#f87171';
      statusText.textContent = `データ収集エラーが${error}件発生しています`;
    } else {
      errorIndicator.style.borderLeftColor = '#4ade80';
      statusIcon.style.background = '#4ade80';
      statusText.textContent = 'システム正常稼働中';
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#log-table-body');
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.ログID || row.id}">
        <td>${formatDateTime(row.収集開始日時)}</td>
        <td>${row.データソース || ''}</td>
        <td>${row.データ種別 || ''}</td>
        <td>${getStatusBadge(row.処理ステータス)}</td>
        <td style="text-align: right;">${(row.収集件数 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(row.エラー件数 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${row.処理時間秒 || 0}秒</td>
        <td style="text-align: right;">${row.データ品質スコア || 0}%</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${row.ログID || row.id}">詳細</button>
          ${row.処理ステータス === '失敗' ? `<button class="action-btn retry-btn" data-id="${row.ログID || row.id}">再実行</button>` : ''}
        </td>
      </tr>
    `).join('');

    container.querySelector('#result-count').textContent = rows.length;
    updateSummary(rows);
  }

  // 初期データ表示
  renderRows(tables[12]?.records || []);

  // 検索・絞り込み機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const dataSource = container.querySelector('#filter-data-source').value;
    const logLevel = container.querySelector('#filter-log-level').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日付検証
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を設定してください');
      return;
    }

    try {
      const rows = await window.aivicApi.list(12);
      if (!rows) return;

      let filteredRows = rows.filter(row => {
        if (dataSource && row.データソース !== dataSource) return false;
        if (logLevel && row.処理ステータス !== logLevel) return false;
        if (startDate && new Date(row.収集開始日時) < new Date(startDate)) return false;
        if (endDate && new Date(row.収集開始日時) > new Date(endDate)) return false;
        return true;
      });

      renderRows(filteredRows);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // CSVエクスポート機能
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const rows = await window.aivicApi.list(12);
      if (!rows) return;

      const headers = ['収集日時', 'データソース', 'データ種別', 'ステータス', '収集件数', 'エラー件数', '処理時間', '品質スコア', 'エラーメッセージ'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(row => [
          `"${formatDateTime(row.収集開始日時)}"`,
          `"${row.データソース || ''}"`,
          `"${row.データ種別 || ''}"`,
          `"${row.処理ステータス || ''}"`,
          row.収集件数 || 0,
          row.エラー件数 || 0,
          row.処理時間秒 || 0,
          row.データ品質スコア || 0,
          `"${(row.エラーメッセージ || '').replace(/"/g, '""')}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `data_collection_logs_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('エクスポートエラー:', error);
      alert('ログエクスポート処理が失敗しました');
    }
  });

  // 自動更新トグル
  container.querySelector('#btn-auto-refresh-toggle').addEventListener('click', () => {
    isAutoRefreshEnabled = !isAutoRefreshEnabled;
    const statusSpan = container.querySelector('#auto-refresh-status');

    if (isAutoRefreshEnabled) {
      statusSpan.textContent = '自動更新: ON';
      autoRefreshInterval = setInterval(async () => {
        const rows = await window.aivicApi.list(12);
        if (rows) renderRows(rows);
      }, 30000); // 30秒間隔
    } else {
      statusSpan.textContent = '自動更新: OFF';
      if (autoRefreshInterval) {
        clearInterval(autoRefreshInterval);
        autoRefreshInterval = null;
      }
    }
  });

  // ログ詳細表示
  function showLogDetail(logId) {
    window.aivicApi.list(12).then(rows => {
      if (!rows) return;

      const log = rows.find(r => (r.ログID || r.id) === logId);
      if (!log) return;

      container.querySelector('#detail-log-id').textContent = log.ログID || log.id;
      container.querySelector('#detail-data-source').textContent = log.データソース || '';
      container.querySelector('#detail-start-time').textContent = formatDateTime(log.収集開始日時);
      container.querySelector('#detail-end-time').textContent = formatDateTime(log.収集終了日時);
      container.querySelector('#detail-status').textContent = log.処理ステータス || '';
      container.querySelector('#detail-quality-score').textContent = `${log.データ品質スコア || 0}%`;
      container.querySelector('#detail-error-message').textContent = log.エラーメッセージ || '(エラーメッセージなし)';

      const retryBtn = container.querySelector('#btn-retry-log');
      if (log.処理ステータス === '失敗') {
        retryBtn.style.display = 'inline-block';
        retryBtn.onclick = () => retryLog(logId);
      } else {
        retryBtn.style.display = 'none';
      }

      container.querySelector('#log-detail-modal').classList.remove('hidden');
    });
  }

  // ログ再実行
  async function retryLog(logId) {
    try {
      const updated = await window.aivicApi.update(12, logId, {
        処理ステータス: '実行中',
        収集開始日時: new Date().toISOString(),
        エラーメッセージ: null
      });

      if (updated) {
        alert('ログの再実行を開始しました');
        container.querySelector('#log-detail-modal').classList.add('hidden');

        // 3秒後に成功状態に更新（実際の処理では外部システムとの連携が必要）
        setTimeout(async () => {
          await window.aivicApi.update(12, logId, {
            処理ステータス: '成功',
            収集終了日時: new Date().toISOString(),
            収集件数: Math.floor(Math.random() * 1000) + 100,
            エラー件数: 0,
            処理時間秒: Math.floor(Math.random() * 30) + 5,
            データ品質スコア: Math.floor(Math.random() * 20) + 80
          });

          const rows = await window.aivicApi.list(12);
          if (rows) renderRows(rows);
        }, 3000);
      }
    } catch (error) {
      console.error('再実行エラー:', error);
      alert('エラーログの再実行が失敗しました');
    }
  }

  // アラート設定表示
  container.querySelector('#btn-alert-settings').addEventListener('click', () => {
    container.querySelector('#alert-settings-modal').classList.remove('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const retryBtn = e.target.closest('.retry-btn');
    const closeModal = e.target.closest('#btn-close-modal, #btn-close-detail');
    const closeAlertModal = e.target.closest('#btn-close-alert-modal, #btn-cancel-alert-settings');

    if (detailBtn) {
      showLogDetail(detailBtn.dataset.id);
    } else if (retryBtn) {
      if (confirm('このログを再実行しますか？')) {
        retryLog(retryBtn.dataset.id);
      }
    } else if (closeModal) {
      container.querySelector('#log-detail-modal').classList.add('hidden');
    } else if (closeAlertModal) {
      container.querySelector('#alert-settings-modal').classList.add('hidden');
    }
  });

  // アラート設定保存
  container.querySelector('#btn-save-alert-settings').addEventListener('click', () => {
    const enabled = container.querySelector('#alert-error-enabled').checked;
    const email = container.querySelector('#alert-email').value;
    const frequency = container.querySelector('#alert-frequency').value;

    if (enabled && !email) {
      alert('通知先メールアドレスを入力してください');
      return;
    }

    // 設定保存（実際の実装では設定テーブルに保存）
    localStorage.setItem('alertSettings', JSON.stringify({ enabled, email, frequency }));
    alert('アラート通知設定を保存しました');
    container.querySelector('#alert-settings-modal').classList.add('hidden');
  });

  // 設定読み込み
  const savedSettings = localStorage.getItem('alertSettings');
  if (savedSettings) {
    const settings = JSON.parse(savedSettings);
    container.querySelector('#alert-error-enabled').checked = settings.enabled;
    container.querySelector('#alert-email').value = settings.email;
    container.querySelector('#alert-frequency').value = settings.frequency;
  }
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistories = [];
  let filteredHistories = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const users = await window.aivicApi.list(0); // ログインユーザーテーブル
      const userSelect = container.querySelector('#select-user');
      if (users) {
        users.forEach(user => {
          const option = document.createElement('option');
          option.value = user.ユーザーID;
          option.textContent = user.ユーザー名 || user.ログインID;
          userSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 履歴一覧を描画する関数
  function renderHistories(histories) {
    const tbody = container.querySelector('#history-tbody');
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageHistories = histories.slice(startIndex, endIndex);

    tbody.innerHTML = pageHistories.map(history => `
      <tr data-id="${history.操作履歴ID || ''}">
        <td>${history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : ''}</td>
        <td>${history.ユーザー名 || ''}</td>
        <td>${history.操作種別 || ''}</td>
        <td>${history.操作画面 || ''}</td>
        <td>${history.IPアドレス || ''}</td>
        <td>
          <span style="padding: 0.2rem 0.5rem; border-radius: 4px; font-size: 0.8rem; 
                       background: ${history.処理結果 === '成功' ? 'var(--primary)' : history.処理結果 === '失敗' || history.処理結果 === 'エラー' ? '#dc3545' : '#6c757d'}; 
                       color: white;">
            ${history.処理結果 || ''}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${history.操作履歴ID || ''}">詳細</button>
        </td>
      </tr>
    `).join('');

    updatePagination(histories.length);
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector('#page-info');
    const prevBtn = container.querySelector('#btn-prev');
    const nextBtn = container.querySelector('#btn-next');

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    prevBtn.disabled = currentPage === 1;
    nextBtn.disabled = currentPage === totalPages || totalPages === 0;
  }

  // 検索フィルター適用
  function applyFilters() {
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const userId = container.querySelector('#select-user').value;
    const operationType = container.querySelector('#select-operation-type').value;
    const screenName = container.querySelector('#input-screen-name').value.toLowerCase();
    const ipAddress = container.querySelector('#input-ip-address').value;
    const result = container.querySelector('#select-result').value;

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。');
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIPAddress(ipAddress)) {
      alert('不正なIPアドレス形式です。正しい形式で入力してください。');
      return;
    }

    filteredHistories = allHistories.filter(history => {
      // 日付範囲フィルター
      if (startDate || endDate) {
        const historyDate = new Date(history.操作日時);
        if (startDate && historyDate < new Date(startDate)) return false;
        if (endDate && historyDate > new Date(endDate + ' 23:59:59')) return false;
      }

      // ユーザーフィルター
      if (userId && history.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && history.操作種別 !== operationType) return false;

      // 画面名フィルター
      if (screenName && !history.操作画面?.toLowerCase().includes(screenName)) return false;

      // IPアドレスフィルター
      if (ipAddress && history.IPアドレス !== ipAddress) return false;

      // 処理結果フィルター
      if (result && history.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderHistories(filteredHistories);
  }

  // IPアドレス形式チェック
  function isValidIPAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip);
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistories.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const modal = container.querySelector('#detail-modal');
    const content = container.querySelector('#detail-content');

    content.innerHTML = `
      <div style="display: grid; gap: 1rem;">
        <div><strong>操作履歴ID:</strong> ${history.操作履歴ID || ''}</div>
        <div><strong>操作日時:</strong> ${history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : ''}</div>
        <div><strong>ユーザー名:</strong> ${history.ユーザー名 || ''}</div>
        <div><strong>操作種別:</strong> ${history.操作種別 || ''}</div>
        <div><strong>操作画面:</strong> ${history.操作画面 || ''}</div>
        <div><strong>操作対象テーブル:</strong> ${history.操作対象テーブル || ''}</div>
        <div><strong>操作対象ID:</strong> ${history.操作対象ID || ''}</div>
        <div><strong>操作内容:</strong> ${history.操作内容 || ''}</div>
        <div><strong>IPアドレス:</strong> ${history.IPアドレス || ''}</div>
        <div><strong>ユーザーエージェント:</strong> ${history.ユーザーエージェント || ''}</div>
        <div><strong>処理結果:</strong> ${history.処理結果 || ''}</div>
        <div><strong>エラーメッセージ:</strong> ${history.エラーメッセージ || ''}</div>
        <div><strong>処理時間:</strong> ${history.処理時間 || ''}ms</div>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // CSV出力
  function exportCSV() {
    if (filteredHistories.length === 0) {
      alert('出力するデータがありません。');
      return;
    }

    // 大量データの場合の警告
    if (filteredHistories.length > 100000) {
      alert('データ量が多すぎるため、CSV出力に失敗しました。検索条件を絞り込んでください。');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作内容', 'IPアドレス', '処理結果'];
    const csvContent = [
      headers.join(','),
      ...filteredHistories.map(history => [
        `"${history.操作日時 ? new Date(history.操作日時).toLocaleString('ja-JP') : ''}"`,
        `"${history.ユーザー名 || ''}"`,
        `"${history.操作種別 || ''}"`,
        `"${history.操作画面 || ''}"`,
        `"${(history.操作内容 || '').replace(/"/g, '""')}"`,
        `"${history.IPアドレス || ''}"`,
        `"${history.処理結果 || ''}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `system_operation_history_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const histories = await window.aivicApi.list(13); // システム操作履歴テーブル
      if (histories) {
        allHistories = histories.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredHistories = [...allHistories];
        renderHistories(filteredHistories);
      } else {
        allHistories = tables[13]?.records || [];
        filteredHistories = [...allHistories];
        renderHistories(filteredHistories);
      }
    } catch (error) {
      console.error('操作履歴の取得に失敗しました:', error);
      allHistories = tables[13]?.records || [];
      filteredHistories = [...allHistories];
      renderHistories(filteredHistories);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#input-start-date').value = '';
    container.querySelector('#input-end-date').value = '';
    container.querySelector('#select-user').value = '';
    container.querySelector('#select-operation-type').value = '';
    container.querySelector('#input-screen-name').value = '';
    container.querySelector('#input-ip-address').value = '';
    container.querySelector('#select-result').value = '';
    filteredHistories = [...allHistories];
    currentPage = 1;
    renderHistories(filteredHistories);
  });

  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-prev').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector('#btn-next').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredHistories.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target === container.querySelector('#detail-modal')) {
      container.querySelector('#detail-modal').classList.add('hidden');
    }
  });

  // 初期化
  loadUsers();
  loadInitialData();
}

function(container, apiUrl, tables) {
  let isProcessing = false;

  // 初期化処理
  function init() {
    // 今日の日付を設定
    const today = new Date().toISOString().split('T')[0];
    const nextMonth = new Date();
    nextMonth.setMonth(nextMonth.getMonth() + 1);
    const nextMonthStr = nextMonth.toISOString().split('T')[0];

    container.querySelector('#prediction-start-date').value = today;
    container.querySelector('#prediction-end-date').value = nextMonthStr;

    // 学習データ期間を過去1年に設定
    const lastYear = new Date();
    lastYear.setFullYear(lastYear.getFullYear() - 1);
    const lastYearStr = lastYear.toISOString().split('T')[0];

    container.querySelector('#learning-start-date').value = lastYearStr;
    container.querySelector('#learning-end-date').value = today;

    loadStores();
    loadCategories();
    setupEventListeners();
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.forEach(store => {
          if (store.有効フラグ) {
            const option = document.createElement('option');
            option.value = store.店舗ID;
            option.textContent = `${store.店舗コード} - ${store.店舗名}`;
            storeSelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗しました:', error);
    }
  }

  // 商品カテゴリ読み込み
  async function loadCategories() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      const categoryContainer = container.querySelector('#category-checkboxes');

      if (products) {
        // カテゴリを重複なしで取得
        const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];

        // 全選択チェックボックス
        const allCheckLabel = document.createElement('label');
        allCheckLabel.style.display = 'block';
        allCheckLabel.innerHTML = '<input type="checkbox" id="category-all"> 全選択';
        categoryContainer.appendChild(allCheckLabel);

        categories.forEach(categoryId => {
          const label = document.createElement('label');
          label.style.display = 'block';
          label.innerHTML = `<input type="checkbox" name="category" value="${categoryId}"> カテゴリ ${categoryId.substring(0, 8)}...`;
          categoryContainer.appendChild(label);
        });

        // 全選択の動作
        container.querySelector('#category-all').addEventListener('change', function() {
          const checkboxes = container.querySelectorAll('input[name="category"]');
          checkboxes.forEach(cb => cb.checked = this.checked);
        });
      }
    } catch (error) {
      console.error('商品カテゴリの読み込みに失敗しました:', error);
    }
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 季節要因スライダー
    const seasonalSlider = container.querySelector('#seasonal-factor');
    const seasonalValue = container.querySelector('#seasonal-value');
    seasonalSlider.addEventListener('input', function() {
      seasonalValue.textContent = this.value + '%';
    });

    // 天候データ取込
    container.querySelector('#btn-weather-import').addEventListener('click', async function() {
      if (isProcessing) return;

      try {
        this.disabled = true;
        this.textContent = '取込中...';

        // 模擬的な天候データ取込処理
        await new Promise(resolve => setTimeout(resolve, 2000));

        const weatherStatus = container.querySelector('#weather-status');
        weatherStatus.textContent = `最終取込: ${new Date().toLocaleString()}`;
        weatherStatus.style.color = 'var(--primary)';

        this.textContent = '天候データ取込';
        this.disabled = false;

      } catch (error) {
        showError('天候データの取得に失敗しました。データソースの設定を確認してください。');
        this.textContent = '天候データ取込';
        this.disabled = false;
      }
    });

    // イベントデータ取込
    container.querySelector('#btn-event-import').addEventListener('click', async function() {
      if (isProcessing) return;

      try {
        this.disabled = true;
        this.textContent = '取込中...';

        // 模擬的なイベントデータ取込処理
        await new Promise(resolve => setTimeout(resolve, 1500));

        const eventStatus = container.querySelector('#event-status');
        eventStatus.textContent = `最終取込: ${new Date().toLocaleString()}`;
        eventStatus.style.color = 'var(--primary)';

        this.textContent = 'イベントデータ取込';
        this.disabled = false;

      } catch (error) {
        showError('イベントデータの取込に失敗しました。ファイル形式を確認してください。');
        this.textContent = 'イベントデータ取込';
        this.disabled = false;
      }
    });

    // AI予測実行
    container.querySelector('#btn-execute-prediction').addEventListener('click', async function() {
      if (isProcessing) return;

      if (!validateForm()) {
        return;
      }

      await executePrediction();
    });
  }

  // フォームバリデーション
  function validateForm() {
    hideError();

    const predictionStart = container.querySelector('#prediction-start-date').value;
    const predictionEnd = container.querySelector('#prediction-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const selectedCategories = container.querySelectorAll('input[name="category"]:checked');
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;

    if (!predictionStart || !predictionEnd) {
      showError('予測期間の開始日と終了日を入力してください');
      return false;
    }

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (selectedCategories.length === 0) {
      showError('商品カテゴリを選択してください');
      return false;
    }

    if (!selectedModel) {
      showError('予測モデルを選択してください');
      return false;
    }

    if (!learningStart || !learningEnd) {
      showError('学習データ期間の開始日と終了日を入力してください');
      return false;
    }

    // 日付バリデーション
    const today = new Date();
    const predStartDate = new Date(predictionStart);
    const predEndDate = new Date(predictionEnd);
    const learnStartDate = new Date(learningStart);
    const learnEndDate = new Date(learningEnd);

    if (predStartDate < today) {
      showError('予測期間に過去の日付は指定できません');
      return false;
    }

    if (predEndDate <= predStartDate) {
      showError('予測期間の終了日は開始日より後の日付を指定してください');
      return false;
    }

    // 1年超チェック
    const oneYearLater = new Date(predStartDate);
    oneYearLater.setFullYear(oneYearLater.getFullYear() + 1);
    if (predEndDate > oneYearLater) {
      showError('予測期間は1年以内で設定してください');
      return false;
    }

    // 学習データ期間チェック
    const learningDays = Math.floor((learnEndDate - learnStartDate) / (1000 * 60 * 60 * 24));
    const predictionDays = Math.floor((predEndDate - predStartDate) / (1000 * 60 * 60 * 24));

    if (learningDays < predictionDays) {
      showError('学習データ期間は予測期間以上に設定してください');
      return false;
    }

    return true;
  }

  // AI予測実行
  async function executePrediction() {
    isProcessing = true;

    try {
      const executeBtn = container.querySelector('#btn-execute-prediction');
      const progressContainer = container.querySelector('#progress-container');
      const resultContainer = container.querySelector('#result-container');

      // UI状態変更
      executeBtn.disabled = true;
      executeBtn.textContent = '処理中...';
      progressContainer.classList.remove('hidden');
      resultContainer.classList.add('hidden');

      // 他の操作を無効化
      disableAllInputs(true);

      // 進捗シミュレーション
      await simulateProgress();

      // 予測結果生成
      const results = await generatePredictionResults();

      // 結果表示
      displayResults(results);

      // 予測結果をデータベースに保存
      await savePredictionResults(results);

    } catch (error) {
      showError('AI予測実行が失敗しました。システム管理者にお問い合わせください。');
      console.error('予測実行エラー:', error);
    } finally {
      isProcessing = false;

      const executeBtn = container.querySelector('#btn-execute-prediction');
      const progressContainer = container.querySelector('#progress-container');

      executeBtn.disabled = false;
      executeBtn.textContent = 'AI予測実行';
      progressContainer.classList.add('hidden');

      // 入力項目を有効化
      disableAllInputs(false);
    }
  }

  // 進捗シミュレーション
  async function simulateProgress() {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const progressPercentage = container.querySelector('#progress-percentage');

    const steps = [
      { text: 'データ収集中...', progress: 20, delay: 1000 },
      { text: '特徴量抽出中...', progress: 40, delay: 1500 },
      { text: 'モデル学習中...', progress: 60, delay: 2000 },
      { text: '予測計算中...', progress: 80, delay: 1500 },
      { text: '結果生成中...', progress: 100, delay: 1000 }
    ];

    for (const step of steps) {
      progressText.textContent = step.text;
      progressBar.style.width = step.progress + '%';
      progressPercentage.textContent = step.progress + '%';
      await new Promise(resolve => setTimeout(resolve, step.delay));
    }
  }

  // 予測結果生成（模擬）
  async function generatePredictionResults() {
    const selectedCategories = container.querySelectorAll('input[name="category"]:checked');
    const results = [];

    // 商品データを取得
    const products = await window.aivicApi.list(2);

    if (products) {
      const categoryIds = Array.from(selectedCategories).map(cb => cb.value);
      const targetProducts = products.filter(p => categoryIds.includes(p.商品カテゴリID) && p.AI予測対象フラグ);

      targetProducts.slice(0, 10).forEach((product, index) => {
        const baseQuantity = Math.floor(Math.random() * 100) + 50;
        const accuracy = Math.floor(Math.random() * 30) + 70; // 70-100%

        results.push({
          商品ID: product.商品ID,
          商品名: product.商品名,
          予測数量: baseQuantity,
          予測精度: accuracy,
          推奨発注数量: Math.ceil(baseQuantity * 1.1) // 10%のバッファ
        });
      });
    }

    return results;
  }

  // 結果表示
  function displayResults(results) {
    const resultContainer = container.querySelector('#result-container');
    const resultSummary = container.querySelector('#result-summary');
    const resultTbody = container.querySelector('#result-tbody');

    // サマリー表示
    const totalProducts = results.length;
    const avgAccuracy = Math.round(results.reduce((sum, r) => sum + r.予測精度, 0) / totalProducts);

    resultSummary.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px;">
        <div style="text-align: center; padding: 16px; background: var(--bg-main); border-radius: 4px;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalProducts}</div>
          <div class="muted">予測対象商品数</div>
        </div>
        <div style="text-align: center; padding: 16px; background: var(--bg-main); border-radius: 4px;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${avgAccuracy}%</div>
          <div class="muted">平均予測精度</div>
        </div>
      </div>
    `;

    // テーブル表示
    resultTbody.innerHTML = results.map(result => `
      <tr data-id="${result.商品ID}">
        <td>${result.商品名}</td>
        <td style="text-align: right;">${result.予測数量.toLocaleString()}</td>
        <td style="text-align: right;">
          <span style="color: ${result.予測精度 >= 80 ? 'var(--primary)' : result.予測精度 >= 60 ? '#ff9500' : '#ff4444'};">
            ${result.予測精度}%
          </span>
        </td>
        <td style="text-align: right;">${result.推奨発注数量.toLocaleString()}</td>
        <td>
          <button class="action-btn secondary" onclick="window.showScreen('scr-1778591852463')">発注へ</button>
        </td>
      </tr>
    `).join('');

    resultContainer.classList.remove('hidden');
  }

  // 予測結果保存
  async function savePredictionResults(results) {
    const storeId = container.querySelector('#store-select').value;
    const predictionDate = new Date().toISOString();
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked').value;

    for (const result of results) {
      const predictionData = {
        店舗ID: storeId,
        商品ID: result.商品ID,
        予測対象日: predictionDate,
        予測数量: result.予測数量,
        予測精度: result.予測精度,
        推奨発注数量: result.推奨発注数量,
        予測モデルバージョン: selectedModel + '_v1.0',
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI自動予測結果'
      };

      await window.aivicApi.save(10, predictionData); // 需要予測結果テーブル
    }
  }

  // 入力項目の有効/無効化
  function disableAllInputs(disabled) {
    const inputs = container.querySelectorAll('input, select, button');
    inputs.forEach(input => {
      if (input.id !== 'btn-execute-prediction') {
        input.disabled = disabled;
      }
    });
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  // エラー非表示
  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.classList.add('hidden');
  }

  // 初期化実行
  init();
}

function(container, apiUrl, tables) {
  let selectedProduct = null;
  let currentPredictionResults = [];

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 店舗データ読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    window.aivicApi.list(1).then(stores => {
      if (stores) {
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
        stores.forEach(store => {
          storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
        });
      }
    });
  }

  // 商品カテゴリ読み込み（商品マスタから重複なしで取得）
  function loadCategories() {
    const categorySelect = container.querySelector('#category-select');
    window.aivicApi.list(2).then(products => {
      if (products) {
        const categories = [...new Set(products.map(p => p.商品カテゴリID).filter(Boolean))];
        categorySelect.innerHTML = '<option value="">すべてのカテゴリ</option>';
        categories.forEach(category => {
          categorySelect.innerHTML += `<option value="${category}">${category}</option>`;
        });
      }
    });
  }

  // 商品一覧表示
  function renderProducts(products) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = products.map(product => `
      <tr data-id="${product.id}">
        <td><input type="radio" name="selected-product" value="${product.id}" class="product-radio"></td>
        <td>${product.商品コード || ''}</td>
        <td>${product.商品名 || ''}</td>
        <td>${product.商品カテゴリID || ''}</td>
        <td class="prediction-qty" data-product-id="${product.id}">-</td>
        <td class="prediction-accuracy" data-product-id="${product.id}">-</td>
        <td><button class="action-btn secondary select-product-btn" data-id="${product.id}">選択</button></td>
      </tr>
    `).join('');
  }

  // 商品検索
  function searchProducts() {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const searchTerm = container.querySelector('#product-search').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    window.aivicApi.list(2).then(products => {
      if (products) {
        let filtered = products.filter(p => p.有効フラグ);

        if (categoryId) {
          filtered = filtered.filter(p => p.商品カテゴリID === categoryId);
        }

        if (searchTerm) {
          filtered = filtered.filter(p => 
            (p.商品名 && p.商品名.includes(searchTerm)) ||
            (p.商品コード && p.商品コード.includes(searchTerm))
          );
        }

        renderProducts(filtered);
      }
    });
  }

  // AI予測実行
  function executeAIPrediction() {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return;
    }

    // 需要予測結果を取得
    window.aivicApi.list(8).then(predictions => {
      if (predictions) {
        currentPredictionResults = predictions.filter(p => 
          p.店舗ID === storeId &&
          p.予測対象日 >= startDate &&
          p.予測対象日<= endDate
        );

        // 予測結果を商品一覧に反映
        currentPredictionResults.forEach(pred => {
          const qtyCell = container.querySelector(`.prediction-qty[data-product-id="${pred.商品ID}"]`);
          const accCell = container.querySelector(`.prediction-accuracy[data-product-id="${pred.商品ID}"]`);
          if (qtyCell) qtyCell.textContent = pred.予測数量 || '-';
          if (accCell) accCell.textContent = pred.予測精度 ? `${pred.予測精度}%` : '-';
        });
      }
    });
  }

  // 商品選択
  function selectProduct(productId) {
    window.aivicApi.list(2).then(products => {
      if (products) {
        selectedProduct = products.find(p => p.id === productId);
        if (selectedProduct) {
          container.querySelector('#selected-product-name').textContent = 
            `選択商品: ${selectedProduct.商品名} (${selectedProduct.商品コード})`;

          // デフォルト値設定
          container.querySelector('#lead-time').value = selectedProduct.リードタイム日数 || 7;
          container.querySelector('#safety-stock').value = selectedProduct.最小発注数量 || 10;

          container.querySelector('#calculation-area').style.display = 'block';
        }
      }
    });
  }

  // 発注量計算
  function calculateOrderQuantity() {
    if (!selectedProduct) {
      showError('商品を選択してください');
      return;
    }

    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 0;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const eventImpact = parseInt(container.querySelector('#event-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;

    // バリデーション
    if (currentStock < 0) {
      showError('在庫数は0以上の値を入力してください');
      return;
    }

    if (isNaN(safetyStock) || safetyStock < 0) {
      showError('安全在庫は0以上の数値を入力してください');
      return;
    }

    if (leadTime < 1 || leadTime > 365) {
      showError('リードタイムは1-365日の範囲で入力してください');
      return;
    }

    if (weatherImpact < 0 || weatherImpact > 200) {
      showError('天候影響度は0-200%の範囲で入力してください');
      return;
    }

    if (eventImpact < 0 || eventImpact > 200) {
      showError('イベント影響度は0-200%の範囲で入力してください');
      return;
    }

    if (seasonalFactor < 0.1 || seasonalFactor > 10) {
      showError('季節補正係数は0.1-10の範囲で入力してください');
      return;
    }

    // 予測数量取得
    const prediction = currentPredictionResults.find(p => p.商品ID === selectedProduct.id);
    const baseDemand = prediction ? prediction.予測数量 : 0;

    // 発注量計算
    const adjustedDemand = baseDemand * (weatherImpact / 100) * (eventImpact / 100) * seasonalFactor;
    const leadTimeDemand = adjustedDemand * (leadTime / 7); // 週単位で計算
    const recommendedQty = Math.max(0, Math.ceil(leadTimeDemand + safetyStock - currentStock));

    // 結果表示
    container.querySelector('#ai-recommended-qty').textContent = recommendedQty;

    // 手動調整値がある場合は最終発注量を更新
    const manualAdjustment = parseInt(container.querySelector('#manual-adjustment').value);
    const finalQty = isNaN(manualAdjustment) ? recommendedQty : manualAdjustment;
    container.querySelector('#final-order-qty').textContent = finalQty;
  }

  // スライダー値更新
  function updateSliderValues() {
    const weatherSlider = container.querySelector('#weather-impact');
    const eventSlider = container.querySelector('#event-impact');
    const weatherValue = container.querySelector('#weather-value');
    const eventValue = container.querySelector('#event-value');

    weatherSlider.addEventListener('input', () => {
      weatherValue.textContent = `${weatherSlider.value}%`;
    });

    eventSlider.addEventListener('input', () => {
      eventValue.textContent = `${eventSlider.value}%`;
    });
  }

  // 手動調整値変更時の処理
  function handleManualAdjustment() {
    const manualInput = container.querySelector('#manual-adjustment');
    manualInput.addEventListener('input', () => {
      const value = parseInt(manualInput.value);
      if (value < 0) {
        showError('発注量は0以上の値を入力してください');
        manualInput.value = '';
        return;
      }

      const finalQty = isNaN(value) ? 
        container.querySelector('#ai-recommended-qty').textContent : value;
      container.querySelector('#final-order-qty').textContent = finalQty;
    });
  }

  // 初期化
  loadStores();
  loadCategories();
  updateSliderValues();
  handleManualAdjustment();

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', searchProducts);
  container.querySelector('#btn-ai-predict').addEventListener('click', executeAIPrediction);
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  // 商品選択イベント
  container.addEventListener('click', (e) => {
    const selectBtn = e.target.closest('.select-product-btn');
    if (selectBtn) {
      const productId = selectBtn.dataset.id;
      selectProduct(productId);

      // ラジオボタンも選択状態にする
      const radio = container.querySelector(`input[value="${productId}"]`);
      if (radio) radio.checked = true;
    }
  });

  // ラジオボタン選択時
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('product-radio')) {
      selectProduct(e.target.value);
    }
  });

  // 発注書作成ボタン
  container.querySelector('#btn-create-order').addEventListener('click', () => {
    if (!selectedProduct) {
      showError('商品を選択してください');
      return;
    }

    const finalQty = container.querySelector('#final-order-qty').textContent;
    if (finalQty === '-' || finalQty === '0') {
      showError('発注量を計算してください');
      return;
    }

    window.showScreen('scr-1778591907544'); // 発注書作成画面
  });
}

function(container, apiUrl, tables) {
  let selectedProducts = [];
  let allProducts = [];
  let stores = [];
  let predictions = [];
  let salesData = [];

  // 再描画関数の定義
  function renderProducts(products) {
    const tbody = container.querySelector("#products-tbody");
    tbody.innerHTML = products.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID) || {};
      const predictedQty = prediction.予測数量 || 0;

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}"></td>
          <td>${product.商品コード || ""}</td>
          <td>${product.商品名 || ""}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>
            ${predictedQty}
            ${predictedQty > 0 ? `<button class="prediction-btn" data-product-id="${product.商品ID}">根拠</button>` : ""}
          </td>
          <td><input type="number" class="input quantity-input" min="0" value="${predictedQty}" data-product-id="${product.商品ID}"></td>
          <td><button class="action-btn secondary add-to-order-btn" data-product-id="${product.商品ID}">追加</button></td>
        </tr>
      `;
    }).join("");
  }

  function renderOrderItems() {
    const tbody = container.querySelector("#order-items-tbody");
    tbody.innerHTML = selectedProducts.map(item => {
      const subtotal = (item.単価 || 0) * (item.発注数量 || 0);
      const prediction = predictions.find(p => p.商品ID === item.商品ID) || {};

      return `
        <tr data-id="${item.商品ID}">
          <td>${item.商品コード || ""}</td>
          <td>${item.商品名 || ""}</td>
          <td>¥${(item.単価 || 0).toLocaleString()}</td>
          <td>${prediction.予測数量 || 0}</td>
          <td><input type="number" class="input quantity-input order-quantity-input" min="0" value="${item.発注数量 || 0}" data-product-id="${item.商品ID}"></td>
          <td>¥${subtotal.toLocaleString()}</td>
          <td><button class="action-btn secondary remove-from-order-btn" data-product-id="${item.商品ID}">削除</button></td>
        </tr>
      `;
    }).join("");

    updateTotalAmount();
  }

  function updateTotalAmount() {
    const total = selectedProducts.reduce((sum, item) => {
      return sum + ((item.単価 || 0) * (item.発注数量 || 0));
    }, 0);
    container.querySelector("#total-amount").textContent = `¥${total.toLocaleString()}`;
  }

  function showError(message) {
    alert(message);
  }

  function validateForm() {
    const storeId = container.querySelector("#store-select").value;
    const orderDate = container.querySelector("#order-date").value;
    const deliveryDate = container.querySelector("#delivery-date").value;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }

    if (!orderDate) {
      showError("発注日付を入力してください");
      return false;
    }

    if (!deliveryDate) {
      showError("納期を指定してください");
      return false;
    }

    if (new Date(deliveryDate) <= new Date(orderDate)) {
      showError("納期は発注日より後の日付を指定してください");
      return false;
    }

    if (selectedProducts.length === 0) {
      showError("発注する商品を選択してください");
      return false;
    }

    for (const product of selectedProducts) {
      if (!product.発注数量 || product.発注数量 <= 0) {
        showError(`${product.商品名}の発注数量は1以上で入力してください`);
        return false;
      }
    }

    return true;
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // 店舗データの読み込み
      const storeData = await window.aivicApi.list(1);
      if (storeData) {
        stores = storeData.filter(s => s.有効フラグ);
        const storeSelect = container.querySelector("#store-select");
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join("");
      }

      // 商品データの読み込み
      const productData = await window.aivicApi.list(2);
      if (productData) {
        allProducts = productData.filter(p => p.有効フラグ);
        renderProducts(allProducts);
      }

      // 需要予測データの読み込み
      const predictionData = await window.aivicApi.list(8);
      if (predictionData) {
        predictions = predictionData;
      }

      // 売上実績データの読み込み
      const salesDataResult = await window.aivicApi.list(3);
      if (salesDataResult) {
        salesData = salesDataResult;
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
    }
  }

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#order-date").value = today;

  // 商品検索
  container.querySelector("#btn-search-products").addEventListener("click", () => {
    const category = container.querySelector("#category-select").value;
    const searchTerm = container.querySelector("#product-search").value.toLowerCase();

    let filteredProducts = allProducts;

    if (category) {
      // カテゴリでフィルタ（簡易実装）
      filteredProducts = filteredProducts.filter(p => 
        p.商品名 && p.商品名.includes(category)
      );
    }

    if (searchTerm) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 && p.商品名.toLowerCase().includes(searchTerm)) ||
        (p.商品コード && p.商品コード.toLowerCase().includes(searchTerm))
      );
    }

    if (filteredProducts.length === 0 && searchTerm) {
      showError("該当する商品が見つかりません");
    }

    renderProducts(filteredProducts);
  });

  // 商品を発注リストに追加
  container.addEventListener("click", (e) => {
    const addBtn = e.target.closest(".add-to-order-btn");
    if (addBtn) {
      const productId = addBtn.dataset.productId;
      const product = allProducts.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      if (quantity <= 0) {
        showError("発注数量は1以上で入力してください");
        return;
      }

      if (isNaN(quantity)) {
        showError("発注数量は数値で入力してください");
        return;
      }

      // 既に追加済みかチェック
      const existingIndex = selectedProducts.findIndex(p => p.商品ID === productId);
      if (existingIndex >= 0) {
        selectedProducts[existingIndex].発注数量 = quantity;
      } else {
        selectedProducts.push({
          ...product,
          発注数量: quantity
        });
      }

      renderOrderItems();
    }

    // 発注リストから削除
    const removeBtn = e.target.closest(".remove-from-order-btn");
    if (removeBtn) {
      const productId = removeBtn.dataset.productId;
      selectedProducts = selectedProducts.filter(p => p.商品ID !== productId);
      renderOrderItems();
    }

    // 予測根拠表示
    const predictionBtn = e.target.closest(".prediction-btn");
    if (predictionBtn) {
      const productId = predictionBtn.dataset.productId;
      showPredictionDetails(productId);
    }

    // モーダル閉じる
    const closeBtn = e.target.closest(".close-btn");
    if (closeBtn) {
      container.querySelectorAll(".modal").forEach(modal => modal.classList.add("hidden"));
    }
  });

  // 発注数量の変更
  container.addEventListener("input", (e) => {
    if (e.target.classList.contains("order-quantity-input")) {
      const productId = e.target.dataset.productId;
      const quantity = parseInt(e.target.value) || 0;

      const product = selectedProducts.find(p => p.商品ID === productId);
      if (product) {
        product.発注数量 = quantity;
        updateTotalAmount();
      }
    }
  });

  // 在庫状況確認
  container.querySelector("#btn-check-stock").addEventListener("click", () => {
    showStockDetails();
  });

  // 過去実績参照
  container.querySelector("#btn-check-history").addEventListener("click", () => {
    showHistoryDetails();
  });

  // 発注総額表示
  container.querySelector("#btn-calculate-total").addEventListener("click", () => {
    updateTotalAmount();
    alert(`発注総額: ${container.querySelector("#total-amount").textContent}`);
  });

  // 発注書作成
  container.querySelector("#btn-create-order").addEventListener("click", async () => {
    if (!validateForm()) {
      return;
    }

    const storeId = container.querySelector("#store-select").value;
    const orderDate = container.querySelector("#order-date").value;
    const deliveryDate = container.querySelector("#delivery-date").value;

    try {
      // 各商品の発注データを保存
      for (const product of selectedProducts) {
        const orderData = {
          店舗ID: storeId,
          商品ID: product.商品ID,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: product.発注数量,
          発注単価: product.単価,
          発注金額: product.単価 * product.発注数量,
          発注方法: "手動発注",
          発注ステータス: "発注済",
          仕入先ID: product.仕入先ID || "default-supplier",
          発注理由: "発注書作成画面からの手動発注",
          自動発注フラグ: false,
          作成者ID: "current-user",
          更新者ID: "current-user"
        };

        await window.aivicApi.save(9, orderData);
      }

      alert("発注書が正常に作成されました");
      window.showScreen('scr-1778591852463');
    } catch (error) {
      console.error("発注書作成エラー:", error);
      showError("発注書の作成に失敗しました");
    }
  });

  function showPredictionDetails(productId) {
    const product = allProducts.find(p => p.商品ID === productId);
    const prediction = predictions.find(p => p.商品ID === productId);

    if (!prediction) {
      showError("予測データが見つかりません");
      return;
    }

    const modal = container.querySelector("#prediction-modal");
    const details = container.querySelector("#prediction-details");

    details.innerHTML = `
      <div class="prediction-item">
        <h4>${product.商品名}</h4>
        <p><strong>予測数量:</strong> ${prediction.予測数量 || 0}個</p>
        <p><strong>予測精度:</strong> ${prediction.予測精度 || 0}%</p>
        <p><strong>推奨発注数量:</strong> ${prediction.推奨発注数量 || 0}個</p>
        <p><strong>予測モデル:</strong> ${prediction.予測モデルバージョン || "不明"}</p>
        <p><strong>予測ステータス:</strong> ${prediction.予測ステータス || "不明"}</p>
        <p><strong>備考:</strong> ${prediction.備考 || "なし"}</p>
      </div>
    `;

    modal.classList.remove("hidden");
  }

  function showStockDetails() {
    const modal = container.querySelector("#stock-modal");
    const details = container.querySelector("#stock-details");

    details.innerHTML = selectedProducts.map(product => `
      <div class="stock-item">
        <h4>${product.商品名}</h4>
        <p><strong>商品コード:</strong> ${product.商品コード}</p>
        <p><strong>発注数量:</strong> ${product.発注数量}個</p>
        <p><strong>単価:</strong> ¥${product.単価.toLocaleString()}</p>
        <p><strong>小計:</strong> ¥${(product.単価 * product.発注数量).toLocaleString()}</p>
        <p><strong>リードタイム:</strong> ${product.リードタイム日数 || 0}日</p>
        <p><strong>最小発注数量:</strong> ${product.最小発注数量 || 0}個</p>
      </div>
    `).join("");

    modal.classList.remove("hidden");
  }

  function showHistoryDetails() {
    const modal = container.querySelector("#history-modal");
    const details = container.querySelector("#history-details");

    // 過去3ヶ月の売上実績を表示（簡易実装）
    const threeMonthsAgo = new Date();
    threeMonthsAgo.setMonth(threeMonthsAgo.getMonth() - 3);

    details.innerHTML = selectedProducts.map(product => {
      const productSales = salesData.filter(s => 
        s.商品ID === product.商品ID && 
        new Date(s.売上日) >= threeMonthsAgo
      );

      const totalSales = productSales.reduce((sum, s) => sum + (s.販売数量 || 0), 0);
      const avgMonthlySales = Math.round(totalSales / 3);

      return `
        <div class="history-item">
          <h4>${product.商品名}</h4>
          <p><strong>過去3ヶ月売上合計:</strong> ${totalSales}個</p>
          <p><strong>月平均売上:</strong> ${avgMonthlySales}個</p>
          <p><strong>現在の発注数量:</strong> ${product.発注数量}個</p>
          <p><strong>実績データ件数:</strong> ${productSales.length}件</p>
        </div>
      `;
    }).join("");

    modal.classList.remove("hidden");
  }

  // モーダル外クリックで閉じる
  container.addEventListener("click", (e) => {
    if (e.target.classList.contains("modal")) {
      e.target.classList.add("hidden");
    }
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentOrders = [];
  let selectedOrderIds = new Set();

  // 今日の日付を表示
  const today = new Date().toLocaleDateString('ja-JP');
  container.querySelector('#order-date').textContent = today;

  // 店舗データを読み込んでプルダウンに設定
  async function loadStores() {
    const storeTableIndex = tables.findIndex(t => t.tableName === '店舗マスタ');
    if (storeTableIndex >= 0) {
      const stores = await window.aivicApi.list(storeTableIndex);
      if (stores) {
        const storeSelect = container.querySelector('#store-select');
        stores.forEach(store => {
          if (store.有効フラグ) {
            const option = document.createElement('option');
            option.value = store.id;
            option.textContent = `${store.店舗コード} - ${store.店舗名}`;
            storeSelect.appendChild(option);
          }
        });
      }
    }
  }

  // 発注データ一覧を描画
  function renderOrderList(orders) {
    const tbody = container.querySelector('#order-list-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted); padding: 40px;">発注対象のデータがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const isSelected = selectedOrderIds.has(order.id);
      const statusBadge = getStatusBadge(order.発注ステータス);
      const isDisabled = order.発注ステータス === '送信済み' || order.発注ステータス === '納品済';

      return `
        <tr data-id="${order.id}" ${isDisabled ? 'style="opacity: 0.6;"' : ''}>
          <td>
            <input type="checkbox" class="order-checkbox" data-id="${order.id}" 
                   ${isSelected ? 'checked' : ''} ${isDisabled ? 'disabled' : ''} />
          </td>
          <td>${order.商品コード || ''}</td>
          <td>${order.商品名 || ''}</td>
          <td style="text-align: right;">${order.予測数量 || 0}</td>
          <td style="text-align: right;">${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td style="text-align: right;">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // ステータスバッジを生成
  function getStatusBadge(status) {
    const badges = {
      '発注済': '<span style="background: #2196f3; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">発注済</span>',
      '送信済み': '<span style="background: #4caf50; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">送信済み</span>',
      '納品済': '<span style="background: #9e9e9e; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">納品済</span>',
      'キャンセル': '<span style="background: #f44336; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">キャンセル</span>'
    };
    return badges[status] || `<span style="background: #ff9800; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">${status}</span>`;
  }

  // 合計金額を更新
  function updateTotalAmount() {
    const selectedOrders = currentOrders.filter(order => selectedOrderIds.has(order.id));
    const total = selectedOrders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    container.querySelector('#success-message').classList.add('hidden');
  }

  // 成功メッセージを表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    container.querySelector('#error-message').classList.add('hidden');
  }

  // メッセージを非表示
  function hideMessages() {
    container.querySelector('#error-message').classList.add('hidden');
    container.querySelector('#success-message').classList.add('hidden');
  }

  // 店舗選択時の処理
  container.querySelector('#store-select').addEventListener('change', async function() {
    const storeId = this.value;
    hideMessages();
    selectedOrderIds.clear();

    if (!storeId) {
      currentOrders = [];
      renderOrderList([]);
      return;
    }

    try {
      const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
      const productTableIndex = tables.findIndex(t => t.tableName === '商品マスタ');
      const demandTableIndex = tables.findIndex(t => t.tableName === '需要予測結果');

      if (orderTableIndex >= 0) {
        const allOrders = await window.aivicApi.list(orderTableIndex);
        const products = productTableIndex >= 0 ? await window.aivicApi.list(productTableIndex) : [];
        const demands = demandTableIndex >= 0 ? await window.aivicApi.list(demandTableIndex) : [];

        if (allOrders) {
          // 選択した店舗の発注データをフィルタリング
          const storeOrders = allOrders.filter(order => order.店舗ID === storeId);

          // 商品情報と需要予測情報を結合
          currentOrders = storeOrders.map(order => {
            const product = products.find(p => p.id === order.商品ID);
            const demand = demands.find(d => d.商品ID === order.商品ID && d.店舗ID === storeId);

            return {
              ...order,
              商品コード: product?.商品コード || '',
              商品名: product?.商品名 || '',
              仕入先名: product?.仕入先名 || '',
              予測数量: demand?.予測数量 || 0
            };
          });

          renderOrderList(currentOrders);
        }
      }
    } catch (error) {
      showError('発注データの取得に失敗しました');
    }
  });

  // 全選択チェックボックスの処理
  container.querySelector('#select-all').addEventListener('change', function() {
    const isChecked = this.checked;
    const checkboxes = container.querySelectorAll('.order-checkbox:not([disabled])');

    checkboxes.forEach(checkbox => {
      checkbox.checked = isChecked;
      const orderId = checkbox.dataset.id;
      if (isChecked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }
    });

    updateTotalAmount();
  });

  // 個別チェックボックスの処理
  container.addEventListener('change', function(e) {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;
      if (e.target.checked) {
        selectedOrderIds.add(orderId);
      } else {
        selectedOrderIds.delete(orderId);
      }

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.order-checkbox:not([disabled])');
      const checkedCheckboxes = container.querySelectorAll('.order-checkbox:not([disabled]):checked');
      const selectAllCheckbox = container.querySelector('#select-all');

      if (checkedCheckboxes.length === 0) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCheckbox.indeterminate = false;
        selectAllCheckbox.checked = true;
      } else {
        selectAllCheckbox.indeterminate = true;
      }

      updateTotalAmount();
    }
  });

  // 送信ボタンの処理
  container.querySelector('#btn-send-selected').addEventListener('click', function() {
    hideMessages();

    if (selectedOrderIds.size === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    // 送信済みデータの重複チェック
    const selectedOrders = currentOrders.filter(order => selectedOrderIds.has(order.id));
    const alreadySent = selectedOrders.filter(order => 
      order.発注ステータス === '送信済み' || order.発注ステータス === '納品済'
    );

    if (alreadySent.length > 0) {
      showError('選択した発注データに送信済みのものが含まれています。重複送信はできません。');
      return;
    }

    // 発注数量0の商品チェック
    const zeroQuantityOrders = selectedOrders.filter(order => (order.発注数量 || 0) === 0);
    if (zeroQuantityOrders.length > 0) {
      showError('発注数量が0の商品が含まれています。発注数量を確認してください。');
      return;
    }

    // 確認ダイアログを表示
    container.querySelector('#selected-count').textContent = selectedOrderIds.size;
    container.querySelector('#send-confirm-dialog').classList.remove('hidden');
  });

  // 送信確認ダイアログのキャンセル
  container.querySelector('#btn-cancel-send').addEventListener('click', function() {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');
  });

  // 送信実行
  container.querySelector('#btn-confirm-send').addEventListener('click', async function() {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');

    try {
      const orderTableIndex = tables.findIndex(t => t.tableName === '発注データ');
      let successCount = 0;
      let failCount = 0;

      // ネットワークエラーのシミュレーション（オフライン状態チェック）
      if (!navigator.onLine) {
        showError('ネットワークエラーが発生しました。接続を確認して再度お試しください。');
        return;
      }

      for (const orderId of selectedOrderIds) {
        try {
          const updated = await window.aivicApi.update(orderTableIndex, orderId, {
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString()
          });

          if (updated) {
            successCount++;
          } else {
            failCount++;
          }
        } catch (error) {
          failCount++;
        }
      }

      if (failCount === 0) {
        showSuccess(`${successCount}件の発注データを正常に送信しました`);
      } else {
        showError(`送信処理が完了しました。成功: ${successCount}件、失敗: ${failCount}件`);
      }

      // データを再読み込み
      const storeId = container.querySelector('#store-select').value;
      if (storeId) {
        container.querySelector('#store-select').dispatchEvent(new Event('change'));
      }

      selectedOrderIds.clear();

    } catch (error) {
      showError('送信処理中にエラーが発生しました');
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', async function() {
    if (currentOrders.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    try {
      const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
        currentOrders.map(order => [
          order.商品コード || '',
          `"${(order.商品名 || '').replace(/"/g, '""')}"`,
          order.予測数量 || 0,
          order.発注数量 || 0,
          `"${(order.仕入先名 || '').replace(/"/g, '""')}"`,
          order.発注金額 || 0,
          order.発注ステータス || ''
        ].join(',')).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注送信データ_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();

      showSuccess('CSVファイルをダウンロードしました');
    } catch (error) {
      showError('CSVエクスポートに失敗しました');
    }
  });

  // 初期化
  loadStores();
}

function(container, apiUrl, tables) {
  let allResults = [];
  let stores = [];
  let products = [];
  let forecasts = [];

  // テーブル再描画関数
  function renderResults(results) {
    const tbody = container.querySelector("#results-tbody");
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id || ''}">
        <td><a href="#" class="product-link" data-product-id="${result.productId || ''}" style="color: var(--primary); text-decoration: none;">${result.productName || ''}</a></td>
        <td>${result.productCode || ''}</td>
        <td style="text-align: right;">${result.forecastDemand || 0}</td>
        <td style="text-align: right;">${result.currentStock || 0}</td>
        <td style="text-align: right;">${result.safetyStock || 0}</td>
        <td style="text-align: right; font-weight: bold; color: var(--primary);">${result.recommendedOrder || 0}</td>
        <td>${result.orderTiming || '-'}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${result.id || ''}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.style.display = "block";
    setTimeout(() => {
      errorDiv.style.display = "none";
    }, 5000);
  }

  // バリデーション
  function validateInputs() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = container.querySelector("#safety-stock").value;
    const leadTime = container.querySelector("#lead-time").value;
    const orderPoint = container.querySelector("#order-point").value;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }
    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return false;
    }
    if (new Date(periodStart) > new Date(periodEnd)) {
      showError("期間の開始日は終了日より前に設定してください");
      return false;
    }
    if (safetyStock && (parseInt(safetyStock) < 0 || parseInt(safetyStock) > 9999)) {
      showError("安全在庫数は0以上9999以下の値を入力してください");
      return false;
    }
    if (leadTime && (parseInt(leadTime) < 1 || parseInt(leadTime) > 365)) {
      showError("リードタイムは1以上365以下の値を入力してください");
      return false;
    }
    if (orderPoint && parseInt(orderPoint) < 0) {
      showError("発注点は0以上の値を入力してください");
      return false;
    }

    return true;
  }

  // 発注量計算実行
  async function executeCalculation() {
    if (!validateInputs()) return;

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 50;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 7;
    const orderPoint = parseInt(container.querySelector("#order-point").value) || 100;

    try {
      // 需要予測データ取得をシミュレート
      const forecastData = await window.aivicApi.list(8); // 需要予測結果テーブル
      if (!forecastData) {
        showError("需要予測データの取得に失敗しました");
        return;
      }

      // 商品データ取得をシミュレート
      const productData = await window.aivicApi.list(2); // 商品マスタテーブル
      if (!productData) {
        showError("在庫データの取得に失敗しました");
        return;
      }

      // カテゴリに応じた商品をフィルタリング
      const categoryProducts = productData.filter(p => 
        p.商品カテゴリID && p.商品カテゴリID.includes(category)
      );

      // 計算結果を生成
      const calculationResults = categoryProducts.map(product => {
        const forecast = forecastData.find(f => f.商品ID === product.商品ID && f.店舗ID === storeId);
        const forecastDemand = forecast ? forecast.予測数量 || 0 : Math.floor(Math.random() * 200) + 50;
        const currentStock = Math.floor(Math.random() * 500) + 100;

        // 発注量計算ロジック
        const demandDuringLeadTime = Math.ceil(forecastDemand * leadTime / 30);
        const recommendedOrder = Math.max(0, (demandDuringLeadTime + safetyStock) - currentStock);

        const orderTiming = currentStock <= orderPoint ? "即時発注" : 
                           currentStock <= (orderPoint + safetyStock) ? "要注意" : "正常";

        return {
          id: `calc_${product.商品ID}`,
          productId: product.商品ID,
          productName: product.商品名,
          productCode: product.商品コード,
          forecastDemand,
          currentStock,
          safetyStock,
          recommendedOrder,
          orderTiming
        };
      });

      allResults = calculationResults;
      renderResults(allResults);

      // サマリー表示更新
      const totalCurrentStock = allResults.reduce((sum, r) => sum + r.currentStock, 0);
      const totalRecommendedOrder = allResults.reduce((sum, r) => sum + r.recommendedOrder, 0);
      const urgentOrders = allResults.filter(r => r.orderTiming === "即時発注").length;

      container.querySelector("#current-stock").textContent = totalCurrentStock.toLocaleString();
      container.querySelector("#recommended-order").textContent = totalRecommendedOrder.toLocaleString();
      container.querySelector("#order-timing").textContent = urgentOrders > 0 ? `${urgentOrders}件 要発注` : "正常";

      // 需要予測結果表示更新
      const forecastDisplay = container.querySelector("#forecast-display");
      forecastDisplay.innerHTML = `
        <div style="color: var(--text);">
          <div style="margin-bottom: 10px;"><strong>対象期間:</strong> ${periodStart} ～ ${periodEnd}</div>
          <div style="margin-bottom: 10px;"><strong>対象商品数:</strong> ${allResults.length}件</div>
          <div style="margin-bottom: 10px;"><strong>総予測需要量:</strong> ${allResults.reduce((sum, r) => sum + r.forecastDemand, 0).toLocaleString()}個</div>
          <div><strong>計算完了時刻:</strong> ${new Date().toLocaleString()}</div>
        </div>
      `;

    } catch (error) {
      showError("計算処理中にエラーが発生しました: " + error.message);
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const storeData = await window.aivicApi.list(1);
      if (storeData) {
        stores = storeData;
        const storeSelect = container.querySelector("#store-select");
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join('');
      }

      // 初期表示
      renderResults([]);
    } catch (error) {
      console.error("初期データ読み込みエラー:", error);
    }
  }

  // 検索機能
  function performSearch() {
    const keyword = container.querySelector("#search-input").value.toLowerCase();
    if (!keyword) {
      renderResults(allResults);
      return;
    }

    const filtered = allResults.filter(result => 
      (result.productName || '').toLowerCase().includes(keyword) ||
      (result.productCode || '').toLowerCase().includes(keyword)
    );
    renderResults(filtered);
  }

  // CSVエクスポート
  function exportCSV() {
    if (!allResults || allResults.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ['商品名', '商品コード', '予測需要量', '現在在庫', '安全在庫', '推奨発注量', '発注タイミング'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allResults.map(result => [
        `"${result.productName || ''}"`,
        `"${result.productCode || ''}"`,
        result.forecastDemand || 0,
        result.currentStock || 0,
        result.safetyStock || 0,
        result.recommendedOrder || 0,
        `"${result.orderTiming || ''}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー設定
  container.querySelector("#btn-calculate").addEventListener("click", executeCalculation);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#period-start").value = "";
    container.querySelector("#period-end").value = "";
    container.querySelector("#safety-stock").value = "";
    container.querySelector("#lead-time").value = "";
    container.querySelector("#order-point").value = "";

    allResults = [];
    renderResults([]);

    container.querySelector("#current-stock").textContent = "-";
    container.querySelector("#recommended-order").textContent = "-";
    container.querySelector("#order-timing").textContent = "-";

    const forecastDisplay = container.querySelector("#forecast-display");
    forecastDisplay.innerHTML = '<div style="color: var(--text-muted);">計算条件を設定して「計算実行」ボタンをクリックしてください</div>';
  });

  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#search-input").addEventListener("keypress", (e) => {
    if (e.key === "Enter") performSearch();
  });

  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const resultId = detailBtn.dataset.id;
      const result = allResults.find(r => r.id === resultId);
      if (result) {
        alert(`商品詳細\n\n商品名: ${result.productName}\n商品コード: ${result.productCode}\n予測需要: ${result.forecastDemand}\n現在在庫: ${result.currentStock}\n推奨発注量: ${result.recommendedOrder}`);
      }
      return;
    }

    const productLink = e.target.closest(".product-link");
    if (productLink) {
      e.preventDefault();
      const productId = productLink.dataset.productId;
      // 商品詳細画面への遷移（実装されている場合）
      console.log("商品詳細画面へ遷移:", productId);
      return;
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const storeSelect = container.querySelector("#store-select");
  const categoryFilter = container.querySelector("#category-filter");
  const productNameSearch = container.querySelector("#product-name-search");
  const productCodeSearch = container.querySelector("#product-code-search");
  const stockStatusFilter = container.querySelector("#stock-status-filter");
  const errorMessage = container.querySelector("#error-message");
  const noResultsMessage = container.querySelector("#no-results-message");

  let allInventoryData = [];
  let storeData = [];
  let productData = [];

  // 在庫状況を判定する関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return 'shortage';
    if (currentStock < safetyStock) return 'shortage';
    if (currentStock > safetyStock * 2) return 'excess';
    return 'normal';
  }

  // 在庫状況のラベルを取得する関数
  function getStockStatusLabel(status) {
    switch(status) {
      case 'normal': return '適正';
      case 'shortage': return '不足';
      case 'excess': return '過剰';
      default: return '適正';
    }
  }

  // 在庫一覧を描画する関数
  function renderInventory(inventoryList) {
    if (!inventoryList || inventoryList.length === 0) {
      tbody.innerHTML = '';
      noResultsMessage.classList.remove('hidden');
      return;
    }

    noResultsMessage.classList.add('hidden');

    tbody.innerHTML = inventoryList.map(item => {
      const product = productData.find(p => p.商品ID === item.商品ID) || {};
      const stockStatus = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
      const statusLabel = getStockStatusLabel(stockStatus);
      const stockClass = item.現在在庫数 === 0 ? 'stock-zero' : '';

      return `
        <tr data-id="${item.在庫ID || item.商品ID}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td class="${stockClass}">${item.現在在庫数 || 0}</td>
          <td>${item.安全在庫数 || 0}</td>
          <td><span class="stock-status ${stockStatus}">${statusLabel}</span></td>
          <td>${item.更新日時 ? new Date(item.更新日時).toLocaleString('ja-JP') : ''}</td>
        </tr>
      `;
    }).join('');
  }

  // 店舗選択肢を設定する関数
  function populateStoreOptions() {
    if (storeData.length > 0) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        storeData.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join('');
    }
  }

  // エラーメッセージを表示する関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
    setTimeout(() => {
      errorMessage.classList.add('hidden');
    }, 5000);
  }

  // バリデーション関数
  function validateSearchInputs() {
    const storeId = storeSelect.value;
    const productCode = productCodeSearch.value.trim();
    const productName = productNameSearch.value.trim();

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    // 商品コードの数値チェック（入力がある場合のみ）
    if (productCode && !/^\d+$/.test(productCode)) {
      showError('商品コードは数値で入力してください');
      return false;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|on\w+\s*=|'|"|;|DROP|SELECT|INSERT|UPDATE|DELETE/i;
    if (dangerousChars.test(productName) || dangerousChars.test(productCode)) {
      showError('不正な文字が含まれています');
      return false;
    }

    // 最大文字数チェック
    if (productName.length > 255) {
      showError('商品名は255文字以内で入力してください');
      return false;
    }

    if (productCode.length > 20) {
      showError('商品コードは20桁以内で入力してください');
      return false;
    }

    return true;
  }

  // 検索フィルタリング関数
  function filterInventory() {
    if (!validateSearchInputs()) {
      return;
    }

    const storeId = storeSelect.value;
    const category = categoryFilter.value;
    const productName = productNameSearch.value.trim().toLowerCase();
    const productCode = productCodeSearch.value.trim();
    const stockStatus = stockStatusFilter.value;

    let filtered = allInventoryData.filter(item => {
      // 店舗フィルタ
      if (storeId && item.店舗ID !== storeId) return false;

      const product = productData.find(p => p.商品ID === item.商品ID) || {};

      // カテゴリフィルタ
      if (category && product.商品カテゴリ !== category) return false;

      // 商品名検索
      if (productName && !product.商品名?.toLowerCase().includes(productName)) return false;

      // 商品コード検索
      if (productCode && product.商品コード !== productCode) return false;

      // 在庫状況フィルタ
      if (stockStatus) {
        const currentStatus = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
        const statusLabel = getStockStatusLabel(currentStatus);
        if (statusLabel !== stockStatus) return false;
      }

      return true;
    });

    renderInventory(filtered);
  }

  // 検索条件クリア関数
  function clearSearchConditions() {
    storeSelect.value = '';
    categoryFilter.value = '';
    productNameSearch.value = '';
    productCodeSearch.value = '';
    stockStatusFilter.value = '';
    errorMessage.classList.add('hidden');
    noResultsMessage.classList.add('hidden');
    tbody.innerHTML = '';
  }

  // CSVエクスポート関数
  function exportToCSV() {
    const storeId = storeSelect.value;
    if (!storeId) {
      showError('店舗を選択してからエクスポートしてください');
      return;
    }

    const filtered = allInventoryData.filter(item => item.店舗ID === storeId);

    const headers = ['商品コード', '商品名', '現在在庫数', '安全在庫数', '在庫状況', '最終更新日時'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...filtered.map(item => {
        const product = productData.find(p => p.商品ID === item.商品ID) || {};
        const stockStatus = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
        const statusLabel = getStockStatusLabel(stockStatus);
        const updateTime = item.更新日時 ? new Date(item.更新日時).toLocaleString('ja-JP') : '';

        return [
          `"${product.商品コード || ''}"`,
          `"${product.商品名 || ''}"`,
          item.現在在庫数 || 0,
          item.安全在庫数 || 0,
          `"${statusLabel}"`,
          `"${updateTime}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeData = stores.filter(store => store.有効フラグ);
        populateStoreOptions();
      }

      // 商品データ読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productData = products.filter(product => product.有効フラグ);
      }

      // 在庫データの生成（実際のシステムでは在庫テーブルから取得）
      // ここでは商品マスタから在庫データを生成
      if (productData.length > 0 && storeData.length > 0) {
        allInventoryData = [];
        storeData.forEach(store => {
          productData.forEach(product => {
            const currentStock = Math.floor(Math.random() * 200);
            const safetyStock = Math.floor(Math.random() * 50) + 10;

            allInventoryData.push({
              在庫ID: `${store.店舗ID}_${product.商品ID}`,
              店舗ID: store.店舗ID,
              商品ID: product.商品ID,
              現在在庫数: currentStock,
              安全在庫数: safetyStock,
              更新日時: new Date().toISOString()
            });
          });
        });
      }

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
      showError('データの読み込みに失敗しました');
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", filterInventory);

  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);

  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // Enter キーでの検索
  [productNameSearch, productCodeSearch].forEach(input => {
    input.addEventListener("keypress", (e) => {
      if (e.key === "Enter") {
        filterInventory();
      }
    });
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentOrderItems = [];
  let storeData = [];
  let productData = [];
  let demandForecastData = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗マスタ
      storeData = await window.aivicApi.list(1) || [];
      // 商品マスタ
      productData = await window.aivicApi.list(2) || [];
      // 需要予測結果
      demandForecastData = await window.aivicApi.list(8) || [];

      renderStoreOptions();
      renderCategoryOptions();
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const validStores = storeData.filter(store => store.有効フラグ);

    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
      validStores.map(store => 
        `<option value="${store.店舗ID}">${store.店舗名} (${store.店舗コード})</option>`
      ).join('');
  }

  // カテゴリ選択肢を描画
  function renderCategoryOptions() {
    const categoryFilter = container.querySelector('#category-filter');
    const categories = [...new Set(productData.map(p => p.商品カテゴリID).filter(Boolean))];

    categoryFilter.innerHTML = '<option value="">全てのカテゴリ</option>' +
      categories.map(cat => `<option value="${cat}">カテゴリ${cat}</option>`).join('');
  }

  // 発注商品一覧を描画
  function renderOrderItems() {
    const tbody = container.querySelector('#order-items-tbody');
    const storeId = container.querySelector('#store-select').value;
    const categoryFilter = container.querySelector('#category-filter').value;

    if (!storeId) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 40px;">店舗を選択してください</td></tr>';
      return;
    }

    // 選択店舗の需要予測データを取得
    let forecasts = demandForecastData.filter(f => f.店舗ID === storeId);

    // カテゴリフィルター適用
    if (categoryFilter) {
      const categoryProducts = productData.filter(p => p.商品カテゴリID === categoryFilter);
      const categoryProductIds = categoryProducts.map(p => p.商品ID);
      forecasts = forecasts.filter(f => categoryProductIds.includes(f.商品ID));
    }

    if (forecasts.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 40px;">データがありません</td></tr>';
      currentOrderItems = [];
      updateSummary();
      return;
    }

    currentOrderItems = forecasts.map(forecast => {
      const product = productData.find(p => p.商品ID === forecast.商品ID) || {};
      return {
        商品ID: forecast.商品ID,
        商品コード: product.商品コード || '',
        商品名: product.商品名 || '',
        予測需要数量: forecast.予測数量 || 0,
        推奨発注数量: forecast.推奨発注数量 || 0,
        現在在庫数量: Math.floor(Math.random() * 100), // 仮の在庫数
        発注数量: forecast.推奨発注数量 || 0,
        発注単価: product.単価 || 0,
        発注金額: (forecast.推奨発注数量 || 0) * (product.単価 || 0),
        selected: false
      };
    });

    tbody.innerHTML = currentOrderItems.map((item, index) => `
      <tr data-index="${index}">
        <td><input type="checkbox" class="item-checkbox" data-index="${index}"></td>
        <td>${item.商品コード}</td>
        <td>${item.商品名}</td>
        <td style="text-align: right;">${item.予測需要数量.toLocaleString()}</td>
        <td style="text-align: right;">${item.推奨発注数量.toLocaleString()}</td>
        <td style="text-align: right;">${item.現在在庫数量.toLocaleString()}</td>
        <td>
          <input type="number" class="input quantity-input" data-index="${index}" 
                 value="${item.発注数量}" min="0" max="999999" style="width: 80px;">
        </td>
        <td style="text-align: right;">¥${item.発注単価.toLocaleString()}</td>
        <td style="text-align: right;" class="amount-cell" data-index="${index}">¥${item.発注金額.toLocaleString()}</td>
        <td>
          <button class="action-btn secondary single-order-btn" data-index="${index}">発注</button>
        </td>
      </tr>
    `).join('');

    updateSummary();
  }

  // 発注数量変更時の金額計算
  function updateAmount(index) {
    const quantityInput = container.querySelector(`input[data-index="${index}"]`);
    const quantity = parseInt(quantityInput.value) || 0;

    // バリデーション
    if (quantity < 0) {
      alert('発注数量は0以上の値を入力してください');
      quantityInput.value = 0;
      return;
    }

    if (quantity > 999999) {
      alert('発注数量が上限値を超えています');
      quantityInput.value = 999999;
      return;
    }

    // 小数点チェック
    if (quantityInput.value.includes('.')) {
      alert('発注数量は整数で入力してください');
      quantityInput.value = Math.floor(quantity);
      return;
    }

    currentOrderItems[index].発注数量 = quantity;
    currentOrderItems[index].発注金額 = quantity * currentOrderItems[index].発注単価;

    const amountCell = container.querySelector(`.amount-cell[data-index="${index}"]`);
    amountCell.textContent = `¥${currentOrderItems[index].発注金額.toLocaleString()}`;

    updateSummary();
  }

  // 合計情報更新
  function updateSummary() {
    const selectedItems = currentOrderItems.filter((item, index) => {
      const checkbox = container.querySelector(`input[data-index="${index}"]`);
      return checkbox && checkbox.checked;
    });

    const selectedCount = selectedItems.length;
    const totalAmount = selectedItems.reduce((sum, item) => sum + item.発注金額, 0);

    container.querySelector('#selected-count').textContent = selectedCount;
    container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;

    const bulkOrderBtn = container.querySelector('#btn-bulk-order');
    bulkOrderBtn.disabled = selectedCount === 0;
  }

  // 発注実行
  async function executeOrder(items) {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return false;
    }

    // 過去日付チェック
    if (new Date(orderDate) < new Date(today)) {
      alert('発注日付は本日以降の日付を選択してください');
      return false;
    }

    // 発注数量チェック
    for (const item of items) {
      if (!item.発注数量 || item.発注数量 <= 0) {
        alert(`${item.商品名}の発注数量を正しく入力してください`);
        return false;
      }
    }

    try {
      for (const item of items) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.商品ID,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
          発注数量: item.発注数量,
          予測数量: item.予測需要数量,
          発注単価: item.発注単価,
          発注金額: item.発注金額,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: 'supplier-001',
          発注理由: 'AI需要予測に基づく発注',
          自動発注フラグ: false,
          作成者ID: 'current-user',
          更新者ID: 'current-user'
        };

        await window.aivicApi.save(9, orderData);
      }

      alert(`${items.length}件の発注を実行しました`);
      return true;
    } catch (error) {
      console.error('発注実行エラー:', error);
      alert('発注実行中にエラーが発生しました');
      return false;
    }
  }

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog(items) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#confirm-content');

    const totalAmount = items.reduce((sum, item) => sum + item.発注金額, 0);

    content.innerHTML = `
      <div style="margin-bottom: 16px;">
        <strong style="color: var(--text);">発注商品: ${items.length}件</strong>
      </div>
      <div style="max-height: 200px; overflow-y: auto; border: 1px solid var(--border); border-radius: 4px; padding: 8px;">
        ${items.map(item => `
          <div style="display: flex; justify-content: space-between; padding: 4px 0; border-bottom: 1px solid var(--border);">
            <span style="color: var(--text);">${item.商品名}</span>
            <span style="color: var(--text);">${item.発注数量}個 × ¥${item.発注単価.toLocaleString()} = ¥${item.発注金額.toLocaleString()}</span>
          </div>
        `).join('')}
      </div>
      <div style="margin-top: 16px; text-align: right;">
        <strong style="color: var(--text); font-size: 16px;">合計金額: ¥${totalAmount.toLocaleString()}</strong>
      </div>
    `;

    dialog.classList.remove('hidden');
  }

  // イベントリスナー設定

  // 店舗選択変更
  container.querySelector('#store-select').addEventListener('change', renderOrderItems);

  // カテゴリフィルター変更
  container.querySelector('#category-filter').addEventListener('change', renderOrderItems);

  // 更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', async () => {
    await loadInitialData();
    renderOrderItems();
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.item-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateSummary();
  });

  // まとめて発注実行ボタン
  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const selectedItems = currentOrderItems.filter((item, index) => {
      const checkbox = container.querySelector(`input[data-index="${index}"]`);
      return checkbox && checkbox.checked;
    });

    if (selectedItems.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    showOrderConfirmDialog(selectedItems);
  });

  // 発注確認ダイアログのボタン
  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-execute-order').addEventListener('click', async () => {
    const selectedItems = currentOrderItems.filter((item, index) => {
      const checkbox = container.querySelector(`input[data-index="${index}"]`);
      return checkbox && checkbox.checked;
    });

    const success = await executeOrder(selectedItems);
    if (success) {
      container.querySelector('#order-confirm-dialog').classList.add('hidden');
      renderOrderItems(); // 画面更新
    }
  });

  // イベントデリゲーション
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      const index = parseInt(e.target.dataset.index);
      updateAmount(index);
    }
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('item-checkbox')) {
      updateSummary();
    }
  });

  container.addEventListener('click', async (e) => {
    // 単品発注ボタン
    if (e.target.classList.contains('single-order-btn')) {
      const index = parseInt(e.target.dataset.index);
      const item = currentOrderItems[index];

      if (!item.発注数量 || item.発注数量 <= 0) {
        alert('発注数量を入力してください');
        return;
      }

      showOrderConfirmDialog([item]);
    }
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  let editingModelId = null;

  // 店舗データとカテゴリデータの準備
  const storeData = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
  const productData = tables.find(t => t.tableName === '商品マスタ')?.records || [];
  const modelData = tables.find(t => t.tableName === '需要予測結果')?.records || [];

  // 商品カテゴリの一意リストを作成
  const categories = [...new Set(productData.map(p => p.商品カテゴリID).filter(Boolean))];

  // 店舗選択肢の設定
  function setupStoreOptions() {
    const storeSelects = container.querySelectorAll('#target-store, #search-store');
    storeSelects.forEach(select => {
      if (select.id === 'search-store') {
        select.innerHTML = '<option value="">全店舗</option>';
      } else {
        select.innerHTML = '<option value="">店舗を選択してください</option>';
      }
      storeData.forEach(store => {
        if (store.有効フラグ) {
          select.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
        }
      });
    });
  }

  // 商品カテゴリチェックボックスの設定
  function setupCategoryCheckboxes() {
    const categoryContainer = container.querySelector('#category-checkboxes');
    categoryContainer.innerHTML = categories.map(categoryId => {
      const product = productData.find(p => p.商品カテゴリID === categoryId);
      const categoryName = product ? `カテゴリ${categoryId.slice(-4)}` : categoryId;
      return `<label><input type="checkbox" value="${categoryId}"> ${categoryName}</label>`;
    }).join('');
  }

  // モデル一覧の再描画
  function renderModels(models) {
    const tbody = container.querySelector('#model-list-tbody');
    tbody.innerHTML = models.map(model => {
      const store = storeData.find(s => s.店舗ID === model.店舗ID);
      const storeName = store ? store.店舗名 : '不明';
      const product = productData.find(p => p.商品ID === model.商品ID);
      const categoryName = product ? `カテゴリ${product.商品カテゴリID?.slice(-4) || ''}` : '不明';

      return `
        <tr data-id="${model.予測結果ID}">
          <td>${model.予測モデルバージョン || 'モデル' + model.予測結果ID.slice(-4)}</td>
          <td>${storeName}</td>
          <td>${categoryName}</td>
          <td>30日</td>
          <td>機械学習</td>
          <td>${model.予測精度 || 85}%</td>
          <td>
            <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; background: var(--primary); color: white;">
              ${model.予測ステータス || '運用中'}
            </span>
          </td>
          <td>${new Date(model.作成日時).toLocaleDateString()}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${model.予測結果ID}">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${model.予測結果ID}">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 重み付け合計の計算
  function updateWeightTotal() {
    const weights = [
      parseInt(container.querySelector('#weight-sales').value) || 0,
      parseInt(container.querySelector('#weight-weather').value) || 0,
      parseInt(container.querySelector('#weight-event').value) || 0,
      parseInt(container.querySelector('#weight-season').value) || 0
    ];
    const total = weights.reduce((sum, w) => sum + w, 0);
    container.querySelector('#weight-total').textContent = total;
  }

  // 学習率の値表示更新
  function updateLearningRateValue() {
    const slider = container.querySelector('#learning-rate');
    const display = container.querySelector('#learning-rate-value');
    display.textContent = parseFloat(slider.value).toFixed(5);
  }

  // バリデーション
  function validateForm() {
    const modelName = container.querySelector('#model-name').value.trim();
    const targetStore = container.querySelector('#target-store').value;
    const predictionPeriod = container.querySelector('input[name="prediction-period"]:checked');
    const algorithm = container.querySelector('#algorithm').value;
    const startDate = container.querySelector('#learning-start-date').value;
    const endDate = container.querySelector('#learning-end-date').value;
    const dataSources = container.querySelectorAll('#model-form input[type="checkbox"]:checked');
    const accuracyTarget = container.querySelector('#accuracy-target').value;
    const seasonalityParam = container.querySelector('#seasonality-param').value;

    // 必須項目チェック
    if (!modelName) {
      alert('モデル名を入力してください。');
      return false;
    }

    if (!targetStore) {
      alert('対象店舗を選択してください。');
      return false;
    }

    // 商品カテゴリの選択チェック
    const selectedCategories = container.querySelectorAll('#category-checkboxes input[type="checkbox"]:checked');
    if (selectedCategories.length === 0) {
      alert('対象商品カテゴリを選択してください。');
      return false;
    }

    if (!predictionPeriod) {
      alert('予測期間を選択してください。');
      return false;
    }

    if (!algorithm) {
      alert('アルゴリズムを選択してください。');
      return false;
    }

    if (!startDate || !endDate) {
      alert('学習期間を設定してください。');
      return false;
    }

    // 日付の妥当性チェック
    const start = new Date(startDate);
    const end = new Date(endDate);
    const today = new Date();

    if (start > end) {
      alert('開始日は終了日より前の日付を設定してください。');
      return false;
    }

    if (start > today || end > today) {
      alert('学習期間に未来の日付は設定できません。');
      return false;
    }

    if (dataSources.length === 0) {
      alert('データソースを選択してください。');
      return false;
    }

    // 精度目標値のチェック
    if (accuracyTarget && (accuracyTarget < 0 || accuracyTarget > 100)) {
      alert('モデル精度目標値は0-100%の範囲で入力してください。');
      return false;
    }

    // 季節性パラメータの数値チェック
    if (seasonalityParam && isNaN(parseFloat(seasonalityParam))) {
      alert('季節性調整パラメータは数値で入力してください。');
      return false;
    }

    // 重み付けの合計チェック
    const total = parseInt(container.querySelector('#weight-total').textContent);
    if (total !== 100) {
      alert('重み付けの合計値が100%でない旨のエラーメッセージが表示され、設定が保存されないこと');
      return false;
    }

    return true;
  }

  // フォームのリセット
  function resetForm() {
    container.querySelector('#model-form').reset();
    container.querySelector('#learning-rate-value').textContent = '0.01';
    updateWeightTotal();
    editingModelId = null;
    container.querySelector('#modal-title').textContent = '新規モデル作成';
    container.querySelector('#btn-save-model').textContent = 'モデル作成';
  }

  // 初期設定
  setupStoreOptions();
  setupCategoryCheckboxes();
  renderModels(modelData);

  // 学習率スライダーのイベント
  container.querySelector('#learning-rate').addEventListener('input', updateLearningRateValue);

  // 重み付け入力のイベント
  ['#weight-sales', '#weight-weather', '#weight-event', '#weight-season'].forEach(id => {
    container.querySelector(id).addEventListener('input', updateWeightTotal);
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const modelName = container.querySelector('#search-model-name').value.toLowerCase();
    const storeId = container.querySelector('#search-store').value;
    const status = container.querySelector('#search-status').value;

    const models = await window.aivicApi.list(12); // 需要予測結果テーブル
    if (!models) return;

    const filtered = models.filter(model => {
      const modelNameMatch = !modelName || (model.予測モデルバージョン || '').toLowerCase().includes(modelName);
      const storeMatch = !storeId || model.店舗ID === storeId;
      const statusMatch = !status || (model.予測ステータス || '運用中') === status;

      return modelNameMatch && storeMatch && statusMatch;
    });

    renderModels(filtered);
  });

  // 新規モデル作成ボタン
  container.querySelector('#btn-new-model').addEventListener('click', () => {
    resetForm();
    container.querySelector('#model-config-modal').classList.remove('hidden');
  });

  // モーダルを閉じる
  function closeModal() {
    container.querySelector('#model-config-modal').classList.add('hidden');
  }

  container.querySelector('#btn-close-modal').addEventListener('click', closeModal);
  container.querySelector('#btn-cancel').addEventListener('click', closeModal);

  // モデル保存
  container.querySelector('#model-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    const formData = {
      店舗ID: container.querySelector('#target-store').value,
      商品ID: productData.find(p => p.商品カテゴリID === container.querySelector('#category-checkboxes input:checked').value)?.商品ID || 'dummy-product-id',
      予測対象日: new Date().toISOString(),
      予測数量: 100,
      予測精度: parseInt(container.querySelector('#accuracy-target').value) || 85,
      推奨発注数量: 100,
      予測モデルバージョン: container.querySelector('#model-name').value,
      実績数量: null,
      予測ステータス: '作成中',
      発注済フラグ: false,
      備考: `予測期間: ${container.querySelector('input[name="prediction-period"]:checked').value}日, アルゴリズム: ${container.querySelector('#algorithm').value}`,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user-id'
    };

    let result;
    if (editingModelId) {
      result = await window.aivicApi.update(12, editingModelId, formData);
    } else {
      result = await window.aivicApi.save(12, formData);
    }

    if (result) {
      alert(editingModelId ? 'モデル設定が正常に変更されました。' : 'モデルが正常に作成されました。');
      closeModal();
      const models = await window.aivicApi.list(12);
      if (models) renderModels(models);
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const id = editBtn.dataset.id;
      const models = await window.aivicApi.list(12);
      const model = models?.find(m => m.予測結果ID === id);

      if (model) {
        editingModelId = id;
        container.querySelector('#modal-title').textContent = 'モデル設定変更';
        container.querySelector('#btn-save-model').textContent = '保存';

        // フォームに既存データを設定
        container.querySelector('#model-name').value = model.予測モデルバージョン || '';
        container.querySelector('#target-store').value = model.店舗ID || '';
        container.querySelector('#accuracy-target').value = model.予測精度 || '';

        container.querySelector('#model-config-modal').classList.remove('hidden');
      }
    }

    if (deleteBtn) {
      if (!confirm('このモデルを削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      const result = await window.aivicApi.delete(12, id);

      if (result !== null) {
        const models = await window.aivicApi.list(12);
        if (models) renderModels(models);
      }
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', async () => {
    const models = await window.aivicApi.list(12);
    if (!models) return;

    const headers = ['モデル名', '対象店舗', '対象商品カテゴリ', '予測期間', 'アルゴリズム', '精度目標値', 'ステータス', '作成日時'];
    const csvData = models.map(model => {
      const store = storeData.find(s => s.店舗ID === model.店舗ID);
      const product = productData.find(p => p.商品ID === model.商品ID);

      return [
        model.予測モデルバージョン || '',
        store?.店舗名 || '',
        product ? `カテゴリ${product.商品カテゴリID?.slice(-4) || ''}` : '',
        '30日',
        '機械学習',
        `${model.予測精度 || 85}%`,
        model.予測ステータス || '運用中',
        new Date(model.作成日時).toLocaleDateString()
      ];
    });

    const csv = '\uFEFF' + [headers, ...csvData].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'model_settings.csv';
    a.click();
    URL.revokeObjectURL(url);
  });

  // 初期データの読み込み
  window.aivicApi.list(12).then(models => {
    if (models) renderModels(models);
  });
}

function(container, apiUrl, tables) {
  // テスト履歴データのテーブルインデックス（システム操作履歴を使用）
  const testHistoryTableIndex = 12;

  // テスト履歴再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.操作日時 ? new Date(r.操作日時).toLocaleString() : ""}</td>
        <td>${r.操作内容 || ""}</td>
        <td>${r.処理結果 || ""}</td>
        <td>${Math.floor(Math.random() * 10) + 1}</td>
        <td>${(Math.random() * 20 + 5).toFixed(2)}%</td>
        <td>${(Math.random() * 50 + 10).toFixed(1)}</td>
        <td>${r.処理時間 || Math.floor(Math.random() * 300 + 30)}ms</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ読み込み
  window.aivicApi.list(testHistoryTableIndex).then(rows => {
    if (rows) {
      // モデルテスト関連の履歴のみフィルタリング
      const testRows = rows.filter(r => r.操作種別 && r.操作種別.includes('テスト'));
      renderTestHistory(testRows);
    }
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#search-input").value;
    const rows = await window.aivicApi.list(testHistoryTableIndex);
    if (rows) {
      const filtered = rows.filter(r => 
        r.操作種別 && r.操作種別.includes('テスト') &&
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      );
      renderTestHistory(filtered);
    }
  });

  // 全店舗選択チェックボックス
  container.querySelector("#select-all-stores").addEventListener("change", (e) => {
    const storeCheckboxes = container.querySelectorAll('input[name="stores"]');
    storeCheckboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 全カテゴリ選択チェックボックス
  container.querySelector("#select-all-categories").addEventListener("change", (e) => {
    const categoryCheckboxes = container.querySelectorAll('input[name="categories"]');
    categoryCheckboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // バリデーション関数
  function validateTestSettings() {
    const model = container.querySelector("#model-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const dataset = container.querySelector('input[name="dataset"]:checked');
    const stores = container.querySelectorAll('input[name="stores"]:checked');
    const categories = container.querySelectorAll('input[name="categories"]:checked');

    if (!model) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (!dataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (stores.length === 0) {
      showError("店舗が選択されていません");
      return false;
    }

    if (categories.length === 0) {
      showError("商品カテゴリが未選択です");
      return false;
    }

    // 存在しないモデルのチェック
    if (model === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません");
      return false;
    }

    return true;
  }

  // テスト実行進行状況シミュレーション
  function simulateTestProgress() {
    const progressDiv = container.querySelector("#test-progress");
    const progressBar = container.querySelector("#progress-bar");
    const progressText = container.querySelector("#progress-text");

    progressDiv.classList.remove("hidden");

    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 15 + 5;
      if (progress > 100) progress = 100;

      progressBar.style.width = progress + "%";

      if (progress < 30) {
        progressText.textContent = "データ前処理中...";
      } else if (progress < 60) {
        progressText.textContent = "モデル実行中...";
      } else if (progress < 90) {
        progressText.textContent = "結果分析中...";
      } else {
        progressText.textContent = "完了";
      }

      if (progress >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          progressDiv.classList.add("hidden");
          showTestResults();
        }, 1000);
      }
    }, 200);
  }

  // テスト結果表示
  function showTestResults() {
    // 予測精度指標表示
    const metricsDiv = container.querySelector("#accuracy-metrics");
    metricsDiv.classList.remove("hidden");

    container.querySelector("#mape-value").textContent = (Math.random() * 15 + 5).toFixed(2);
    container.querySelector("#rmse-value").textContent = (Math.random() * 40 + 15).toFixed(1);
    container.querySelector("#mae-value").textContent = (Math.random() * 30 + 10).toFixed(1);
    container.querySelector("#r2-value").textContent = (0.7 + Math.random() * 0.25).toFixed(3);
    container.querySelector("#execution-time").textContent = (Math.random() * 200 + 50).toFixed(0) + "秒";

    // グラフ表示
    const chartDiv = container.querySelector("#comparison-chart");
    chartDiv.classList.remove("hidden");
    drawComparisonChart();

    // モデルパラメータ表示
    const paramsDiv = container.querySelector("#model-parameters");
    paramsDiv.classList.remove("hidden");

    // テスト履歴に追加
    const testData = {
      操作種別: "モデルテスト実行",
      操作内容: container.querySelector("#model-select").value,
      処理結果: "成功",
      操作日時: new Date().toISOString(),
      処理時間: Math.floor(Math.random() * 300 + 30),
      ユーザーID: "current-user"
    };

    window.aivicApi.save(testHistoryTableIndex, testData).then(() => {
      return window.aivicApi.list(testHistoryTableIndex);
    }).then(rows => {
      if (rows) {
        const testRows = rows.filter(r => r.操作種別 && r.操作種別.includes('テスト'));
        renderTestHistory(testRows);
      }
    });
  }

  // 比較グラフ描画
  function drawComparisonChart() {
    const canvas = container.querySelector("#chart-canvas");
    const ctx = canvas.getContext("2d");

    // Canvas サイズ設定
    canvas.width = 800;
    canvas.height = 400;

    // 背景クリア
    ctx.fillStyle = "#1a2332";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ生成
    const days = 30;
    const actualData = [];
    const predictedData = [];

    for (let i = 0; i < days; i++) {
      const base = 100 + Math.sin(i * 0.2) * 30;
      actualData.push(base + (Math.random() - 0.5) * 20);
      predictedData.push(base + (Math.random() - 0.5) * 15);
    }

    // グラフ描画エリア設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = "#9fb0d1";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績値線描画
    ctx.strokeStyle = "#00d4ff";
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - (actualData[i] / 150) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値線描画
    ctx.strokeStyle = "#ff6a00";
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (i / (days - 1)) * chartWidth;
      const y = canvas.height - padding - (predictedData[i] / 150) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例描画
    ctx.fillStyle = "#d0e4ff";
    ctx.font = "14px Arial";
    ctx.fillText("実績値", padding, 30);
    ctx.fillStyle = "#00d4ff";
    ctx.fillRect(padding - 20, 22, 15, 3);

    ctx.fillStyle = "#d0e4ff";
    ctx.fillText("予測値", padding + 80, 30);
    ctx.fillStyle = "#ff6a00";
    ctx.fillRect(padding + 60, 22, 15, 3);
  }

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", () => {
    if (validateTestSettings()) {
      simulateTestProgress();
    }
  });

  // テスト結果エクスポートボタン
  container.querySelector("#btn-test-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(testHistoryTableIndex);
    if (rows) {
      const testRows = rows.filter(r => r.操作種別 && r.操作種別.includes('テスト'));

      const headers = ["テスト日時", "モデル名", "テスト結果", "MAPE", "RMSE", "実行時間"];
      const csvContent = "\uFEFF" + headers.join(",") + "\n" + 
        testRows.map(r => [
          r.操作日時 ? new Date(r.操作日時).toLocaleString() : "",
          r.操作内容 || "",
          r.処理結果 || "",
          (Math.random() * 20 + 5).toFixed(2) + "%",
          (Math.random() * 50 + 10).toFixed(1),
          (r.処理時間 || Math.floor(Math.random() * 300 + 30)) + "ms"
        ].map(field => `"${field}"`).join(",")).join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "model_test_results.csv";
      link.click();
    }
  });

  // 行レベル操作（削除・詳細表示）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      await window.aivicApi.delete(testHistoryTableIndex, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(testHistoryTableIndex);
      if (rows) {
        const testRows = rows.filter(r => r.操作種別 && r.操作種別.includes('テスト'));
        renderTestHistory(testRows);
      }
    }

    const viewBtn = e.target.closest(".view-detail-btn");
    if (viewBtn) {
      // 詳細表示（モデル設定画面に遷移）
      window.showScreen("scr-1778591984641");
    }
  });
}

function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let validationPassed = false;
  let isProcessing = false;

  // モデル一覧を取得して表示
  async function loadModels() {
    // サンプルモデルデータ（実際の実装では需要予測モデルテーブルから取得）
    currentModels = [
      { id: 'model-001', name: 'LSTM需要予測モデルv2.1', version: 'v2.1', accuracy: 92.5, status: '検証済み', created: '2024-01-15' },
      { id: 'model-002', name: 'RandomForest需要予測モデルv1.8', version: 'v1.8', accuracy: 89.3, status: '検証済み', created: '2024-01-10' },
      { id: 'model-003', name: 'XGBoost需要予測モデルv3.0', version: 'v3.0', accuracy: 94.1, status: '検証済み', created: '2024-01-20' }
    ];

    const modelSelect = container.querySelector('#model-select');
    modelSelect.innerHTML = '<option value="">モデルを選択してください</option>';
    currentModels.forEach(model => {
      const option = document.createElement('option');
      option.value = model.id;
      option.textContent = `${model.name} (精度: ${model.accuracy}%)`;
      modelSelect.appendChild(option);
    });
  }

  // 店舗一覧を取得して表示
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      currentStores = stores.filter(store => store.有効フラグ);
      renderStoreList();
    }
  }

  function renderStoreList() {
    const storeList = container.querySelector('#store-list');
    storeList.innerHTML = currentStores.map(store => `
      <label style="display: flex; align-items: center; gap: 8px; margin-bottom: 8px; color: var(--text);">
        <input type="checkbox" class="store-checkbox" value="${store.店舗ID}" style="margin: 0;">
        ${store.店舗名} (${store.店舗コード})
      </label>
    `).join('');
  }

  // モデル詳細情報を表示
  function showModelDetails(modelId) {
    const model = currentModels.find(m => m.id === modelId);
    const detailsDiv = container.querySelector('#model-details');

    if (model) {
      detailsDiv.innerHTML = `
        <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px;">
          <div><strong>モデル名:</strong> ${model.name}</div>
          <div><strong>バージョン:</strong> ${model.version}</div>
          <div><strong>予測精度:</strong> ${model.accuracy}%</div>
          <div><strong>ステータス:</strong> ${model.status}</div>
          <div><strong>作成日:</strong> ${model.created}</div>
          <div><strong>最終更新:</strong> ${model.created}</div>
        </div>
      `;
      detailsDiv.style.color = 'var(--text)';
    } else {
      detailsDiv.innerHTML = 'モデルを選択してください';
      detailsDiv.style.color = 'var(--text-muted)';
    }
  }

  // 適用前検証を実行
  async function runValidation(modelId) {
    const validationDiv = container.querySelector('#validation-results');
    validationDiv.innerHTML = '検証中...';
    validationDiv.style.color = 'var(--text-muted)';

    // 模擬検証処理
    await new Promise(resolve => setTimeout(resolve, 2000));

    const model = currentModels.find(m => m.id === modelId);
    const isValid = model && model.accuracy > 85; // 精度85%以上で検証OK

    validationPassed = isValid;

    if (isValid) {
      validationDiv.innerHTML = `
        <div style="color: #4ade80; margin-bottom: 12px;"><strong>✓ 検証合格</strong></div>
        <div>• データ品質チェック: 合格</div>
        <div>• 精度閾値チェック: 合格 (${model.accuracy}% ≥ 85%)</div>
        <div>• モデル整合性チェック: 合格</div>
        <div>• 依存関係チェック: 合格</div>
      `;
      validationDiv.style.color = 'var(--text)';
    } else {
      validationDiv.innerHTML = `
        <div style="color: #f87171; margin-bottom: 12px;"><strong>✗ 検証失敗</strong></div>
        <div>• データ品質チェック: 合格</div>
        <div>• 精度閾値チェック: 不合格 (精度が基準値85%を下回っています)</div>
        <div>• モデル整合性チェック: 合格</div>
      `;
      validationDiv.style.color = 'var(--text)';
    }

    updateApplyButton();
  }

  // 影響範囲分析を表示
  function showImpactAnalysis() {
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const impactDiv = container.querySelector('#impact-analysis');

    if (selectedStores.length === 0) {
      impactDiv.innerHTML = '適用対象店舗を選択してください';
      impactDiv.style.color = 'var(--text-muted)';
      return;
    }

    const storeCount = selectedStores.length;
    const totalStores = currentStores.length;
    const impactPercentage = Math.round((storeCount / totalStores) * 100);

    impactDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px;">
        <div><strong>対象店舗数:</strong> ${storeCount}店舗</div>
        <div><strong>全体に占める割合:</strong> ${impactPercentage}%</div>
        <div><strong>予想処理時間:</strong> 約${Math.ceil(storeCount * 2)}分</div>
        <div><strong>影響度:</strong> ${impactPercentage > 50 ? '大' : impactPercentage > 20 ? '中' : '小'}</div>
      </div>
      <div style="margin-top: 12px; padding: 12px; background: rgba(59, 130, 246, 0.1); border-radius: 4px; border-left: 3px solid #3b82f6;">
        <strong>注意事項:</strong> 適用中は対象店舗の需要予測処理が一時停止されます
      </div>
    `;
    impactDiv.style.color = 'var(--text)';
  }

  // 適用実行ボタンの状態を更新
  function updateApplyButton() {
    const applyBtn = container.querySelector('#btn-apply');
    const modelSelected = container.querySelector('#model-select').value;
    const storesSelected = container.querySelectorAll('.store-checkbox:checked').length > 0;
    const startDateTime = container.querySelector('#start-datetime').value;

    const canApply = modelSelected && storesSelected && startDateTime && validationPassed && !isProcessing;
    applyBtn.disabled = !canApply;
  }

  // 進捗バーを更新
  function updateProgress(percentage, text) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressBar.style.width = `${percentage}%`;
    progressText.textContent = text;
  }

  // ログを追加
  function addLog(message, type = 'info') {
    const logDiv = container.querySelector('#result-log');
    const timestamp = new Date().toLocaleString();
    const color = type === 'error' ? '#f87171' : type === 'success' ? '#4ade80' : 'var(--text)';

    logDiv.innerHTML += `<div style="color: ${color};">[${timestamp}] ${message}</div>`;
    logDiv.scrollTop = logDiv.scrollHeight;
  }

  // モデル適用処理を実行
  async function executeModelApplication() {
    if (isProcessing) return;

    const modelId = container.querySelector('#model-select').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value);
    const startDateTime = container.querySelector('#start-datetime').value;

    // 入力検証
    if (!modelId) {
      alert('適用対象モデルを選択してください');
      return;
    }

    if (selectedStores.length === 0) {
      alert('適用対象店舗を選択してください');
      return;
    }

    if (!startDateTime) {
      alert('適用開始日時を入力してください');
      return;
    }

    // 過去日時チェック
    const startDate = new Date(startDateTime);
    const now = new Date();
    if (startDate < now) {
      alert('適用開始日時には現在日時以降を指定してください');
      return;
    }

    if (!validationPassed) {
      alert('適用前検証に合格していないため、モデル適用を実行できません');
      return;
    }

    if (!confirm('モデルの本番適用を実行しますか？')) {
      return;
    }

    isProcessing = true;
    updateApplyButton();

    const model = currentModels.find(m => m.id === modelId);
    addLog(`モデル適用処理を開始します: ${model.name}`);
    addLog(`対象店舗数: ${selectedStores.length}店舗`);

    try {
      // 段階的な処理をシミュレート
      const stages = [
        { name: 'モデル検証', duration: 2000, progress: 20 },
        { name: 'バックアップ作成', duration: 3000, progress: 40 },
        { name: 'モデルデプロイ', duration: 4000, progress: 70 },
        { name: '本番切替', duration: 2000, progress: 90 },
        { name: '動作確認', duration: 1000, progress: 100 }
      ];

      for (const stage of stages) {
        updateProgress(stage.progress, `${stage.name}中...`);
        addLog(`${stage.name}を開始しています...`);

        await new Promise(resolve => setTimeout(resolve, stage.duration));

        addLog(`${stage.name}が完了しました`, 'success');
      }

      updateProgress(100, '適用完了');
      addLog('モデルの本番適用が正常に完了しました', 'success');
      addLog(`適用完了時刻: ${new Date().toLocaleString()}`);

    } catch (error) {
      addLog(`エラーが発生しました: ${error.message}`, 'error');
      updateProgress(0, 'エラー');
    } finally {
      isProcessing = false;
      updateApplyButton();
    }
  }

  // ロールバック処理を実行
  async function executeRollback() {
    if (!confirm('現在のモデルを前バージョンにロールバックしますか？')) {
      return;
    }

    addLog('ロールバック処理を開始します...');
    updateProgress(0, 'ロールバック中...');

    try {
      const stages = [
        { name: 'バックアップ確認', progress: 25 },
        { name: '前バージョン復元', progress: 60 },
        { name: 'サービス切替', progress: 85 },
        { name: '動作確認', progress: 100 }
      ];

      for (const stage of stages) {
        updateProgress(stage.progress, `${stage.name}中...`);
        addLog(`${stage.name}を実行中...`);
        await new Promise(resolve => setTimeout(resolve, 2000));
        addLog(`${stage.name}が完了しました`, 'success');
      }

      updateProgress(100, 'ロールバック完了');
      addLog('ロールバック処理が正常に完了しました', 'success');

    } catch (error) {
      addLog(`ロールバック中にエラーが発生しました: ${error.message}`, 'error');
      updateProgress(0, 'エラー');
    }
  }

  // イベントリスナーの設定
  container.querySelector('#model-select').addEventListener('change', (e) => {
    const modelId = e.target.value;
    if (modelId) {
      showModelDetails(modelId);
      runValidation(modelId);
    } else {
      showModelDetails(null);
      container.querySelector('#validation-results').innerHTML = 'モデルを選択すると検証が実行されます';
      container.querySelector('#validation-results').style.color = 'var(--text-muted)';
      validationPassed = false;
    }
    updateApplyButton();
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    showImpactAnalysis();
    updateApplyButton();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      showImpactAnalysis();
      updateApplyButton();

      // 全選択チェックボックスの状態を更新
      const allCheckboxes = container.querySelectorAll('.store-checkbox');
      const checkedCheckboxes = container.querySelectorAll('.store-checkbox:checked');
      const selectAllCheckbox = container.querySelector('#select-all-stores');

      selectAllCheckbox.checked = allCheckboxes.length === checkedCheckboxes.length;
      selectAllCheckbox.indeterminate = checkedCheckboxes.length > 0 && checkedCheckboxes.length < allCheckboxes.length;
    }
  });

  container.querySelector('#start-datetime').addEventListener('change', updateApplyButton);

  container.querySelector('#btn-apply').addEventListener('click', executeModelApplication);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期化
  loadModels();
  loadStores();

  // 現在時刻を適用開始日時のデフォルト値として設定
  const now = new Date();
  now.setMinutes(now.getMinutes() + 10); // 10分後をデフォルトに
  container.querySelector('#start-datetime').value = now.toISOString().slice(0, 16);

  addLog('モデル本番適用処理画面を初期化しました');
}
